const KEY='debitar_ops_v05',OLD='debitar_ops_v04';const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const fmt=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(+n||0);const num=n=>new Intl.NumberFormat('es-CL',{maximumFractionDigits:1}).format(+n||0);const uid=p=>p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);const ym=d=>(d||'').slice(0,7);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const expenseDefaults=[['PENSION BASTI','Familia',150000,12],['PENSION EDUARDO','Familia',100000,20],['ARRIENDO','Vivienda',500000,1],['MERCADERIA','Hogar',150000,3],['CGE','Servicios básicos',90000,15],['AGUAS ANDINAS','Servicios básicos',35000,20],['GAS','Servicios básicos',45000,10],['WOM INTERNET HOGAR','Telecomunicaciones',15000,15],['TRASLADO PASCAL','Movilización',25000,20],['INTERNET MOVIL DANIEL','Telecomunicaciones',26500,10],['DEUDA ELY CARLA','Deudas',60000,14],['CUOTA POLLA','Deudas',50000,4],['CUOTA CELULAR ARAMZA','Deudas',30000,15],['INTERNET CARLA','Telecomunicaciones',22000,10],['TAG','Auto',30000,4],['BENCINA','Auto',80000,15],['SEGURO AUTO FALABELLA','Auto',38000,22],['PAGOS PENDIENTES','Otros',77000,5]].map((x,i)=>({id:'e'+(i+1),name:x[0],category:x[1],amount:x[2],day:x[3],active:true}));
const seed={version:3,selectedMonth:'2026-10',wallets:[{id:'w1',name:'BancoEstado',type:'Propia',active:true,balance:0},{id:'w2',name:'BCI',type:'Propia',active:true,balance:0},{id:'w3',name:'Banco Falabella',type:'Propia',active:true,balance:0},{id:'w4',name:'MACH',type:'Respaldo',active:false,balance:0},{id:'w5',name:'Santander',type:'Sin acceso',active:false,balance:0},{id:'w6',name:'Banco de Chile · pareja',type:'Tercero / resguardo',active:true,balance:0}],clients:[['Transportes Arnaldo Jesús Díaz Burgoa E.I.R.L.',80000,12],['MYH SPA',80000,22],['Transportes Agurto',100000,7],['Botillería Juanito',60000,12],['ALPERPRO SPA',60000,20],['Chico Truckis SPA',60000,5],['Dagoberto Millar',40000,12],['Donde la Jenny SPA',40000,20],['Instalaciones y Serv Navalec SPA',40000,20],['Óptica Marjorie Marion Sierra Moya',45000,15]].map((x,i)=>({id:'c'+(i+1),rut:'',name:x[0],reps:[],fee:x[1],day:x[2],email:'',phone:'',vault:null,active:true})),expenseTemplates:expenseDefaults,expenseMonths:{},debts:[{id:'d1',name:'Ian',date:'2026-10-15',amount:100000,status:'Pendiente'},{id:'d2',name:'Alex',date:'2026-10-31',amount:300000,status:'Pendiente'},{id:'d3',name:'Papá',date:'2026-12-01',amount:50000,status:'Pendiente'}],incomes:[],transfers:[],collections:[],uberTurns:[],uberSettings:{fuelPrice:0,efficiency:0,wearKm:0,retention:0,startCapital:13000},debitarSessions:[],workSettings:{monthlyHours:180},objectives:[{id:'o1',name:'Fondo de emergencia',target:3000000,current:25000},{id:'o2',name:'Ingreso mensual objetivo',target:3000000,current:0}],otherSources:[],uberTrips:[],uberActiveShift:null,objectiveContributions:[],tasks:[],prospects:[]};
function clone(x){return JSON.parse(JSON.stringify(x))}function load(){let v=localStorage.getItem(KEY);if(v){let x=Object.assign(clone(seed),JSON.parse(v));x.uberTrips=x.uberTrips||[];x.objectiveContributions=x.objectiveContributions||[];x.tasks=x.tasks||[];x.prospects=x.prospects||[];return x}let old=localStorage.getItem(OLD);if(old){try{let o=JSON.parse(old),x=Object.assign(clone(seed),o);x.uberTrips=x.uberTrips||[];x.objectiveContributions=x.objectiveContributions||[];x.tasks=x.tasks||[];x.prospects=x.prospects||[];localStorage.setItem(KEY,JSON.stringify(x));return x}catch{}}return clone(seed)}let state=load(),page='Inicio',vaultSession=null;function save(msg){localStorage.setItem(KEY,JSON.stringify(state));if(msg)toast(msg)}
function monthExpenses(m=state.selectedMonth){return state.expenseTemplates.filter(e=>e.active).map(e=>{let ov=(state.expenseMonths[m]||{})[e.id]||{};return {...e,...ov,base:e.amount,status:ov.status||'Pendiente',paidAmount:+ov.paidAmount||0,wallet:ov.wallet||'',paidDate:ov.paidDate||''}})}function debtsM(m=state.selectedMonth){return state.debts.filter(d=>ym(d.date)===m)}function incomesM(m=state.selectedMonth){return state.incomes.filter(i=>ym(i.date)===m)}function turnsM(m=state.selectedMonth){return state.uberTurns.filter(t=>ym(t.start)===m)}function sessionsM(m=state.selectedMonth){return state.debitarSessions.filter(s=>ym(s.start)===m)}function collectionsM(m=state.selectedMonth){return state.collections.filter(c=>c.month===m)}
function metrics(m=state.selectedMonth){let ex=monthExpenses(m),ds=debtsM(m),ins=incomesM(m),ts=turnsM(m),cols=collectionsM(m);let recurring=ex.reduce((a,e)=>a+(+e.amount||0),0),debtDue=ds.filter(d=>d.status!=='Pagada').reduce((a,d)=>a+d.amount,0)+ds.filter(d=>d.status==='Pagada').reduce((a,d)=>a+d.amount,0),due=recurring+debtDue;let paid=ex.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0)+ds.filter(d=>d.status==='Pagada').reduce((a,d)=>a+d.amount,0);let work=ins.filter(i=>i.source==='Trabajo dependiente').reduce((a,i)=>a+i.amount,0),other=ins.filter(i=>!['Trabajo dependiente','DEBITAR','Uber'].includes(i.source)&&!/saldo\s*(inicial|disponible)/i.test(i.note||'')).reduce((a,i)=>a+i.amount,0),debitar=cols.filter(c=>c.status==='Cobrado').reduce((a,c)=>a+c.amount,0)+ins.filter(i=>i.source==='DEBITAR').reduce((a,i)=>a+i.amount,0),uber=ts.reduce((a,t)=>a+t.net,0),income=work+other+debitar+uber,expectedDebitar=state.clients.filter(c=>c.active).reduce((a,c)=>a+c.fee,0),nonUber=work+other+debitar,uberTarget=Math.max(0,due-nonUber),uberMissing=Math.max(0,uberTarget-uber),pending=Math.max(0,due-paid),debHours=sessionsM(m).reduce((a,s)=>a+s.hours,0),uberHours=ts.reduce((a,t)=>a+t.hours,0),workHours=work?state.workSettings.monthlyHours:0;return{recurring,debtDue,due,paid,pending,work,other,debitar,uber,income,expectedDebitar,uberTarget,uberMissing,result:income-due,debHours,uberHours,workHours}}
const nav=['Inicio','Finanzas','Gastos','Deudas','DEBITAR','Uber','Tareas','Objetivos','Reportes','Configuración'];
const dockLeft=[['Inicio','⌂'],['Finanzas','◫'],['Gastos','↓'],['Deudas','◈']];
const dockRight=[['DEBITAR','D'],['Uber','U'],['Proyectos','P'],['Tareas','✓'],['Objetivos','◎'],['Reportes','▤'],['Configuración','⚙']];
function dockButtons(items){return items.map(([n,ic])=>`<button data-p="${n}" class="dockbtn ${n===page?'on':''}" title="${n}"><span class="dockicon">${ic}</span><span class="docklabel">${n}</span></button>`).join('')}
function shell(){document.querySelector('#app').innerHTML=`<div class="shell shell-v061"><aside class="side side-left"><img class="logo" src="https://danielmunoz-debitar.github.io/centro-operaciones/assets/logo-debitar.png"><div class="nav docknav">${dockButtons(dockLeft)}</div></aside><main class="main"><div class="top"><div class="title"><h1>${page}</h1><p>Centro de Operaciones · v0.6.1 · control y gestión DEBITAR</p></div><input class="month" id="month" type="month" value="${state.selectedMonth}"></div><div id="view"></div></main><aside class="side side-right"><div class="right-brand">DEBITAR</div><div class="nav docknav">${dockButtons(dockRight)}</div></aside></div>`;$$('[data-p]').forEach(b=>b.onclick=()=>{page=b.dataset.p;shell()});$('#month').onchange=e=>{state.selectedMonth=e.target.value;save();render()};render()}
function render(){let fn={'Inicio':dashboard,'Finanzas':finances,'Gastos':expenses,'Deudas':debts,'DEBITAR':debitar,'Uber':uber,'Tareas':tasksPage,'Objetivos':objectives,'Reportes':reports,'Configuración':settings}[page];$('#view').innerHTML=fn();bind()}
function kpi(t,v,s=''){return `<div class="card kpi"><small>${t}</small><b>${v}</b><em>${s}</em></div>`}function pct(v,t){return t?Math.round(v/t*100):0}function dashboard(){let m=metrics();let time=m.workHours+m.debHours+m.uberHours;return `<div class="grid kpis">${kpi('Ingresos del mes',fmt(m.income),'Trabajo + DEBITAR + Uber + otros')}${kpi('Gastos / obligaciones',fmt(m.due),`Pagado ${fmt(m.paid)} · pendiente ${fmt(m.pending)}`)}${kpi('Resultado proyectado',fmt(m.result),m.result>=0?'Superávit':'Déficit')}${kpi('Meta Uber faltante',fmt(m.uberMissing),`Meta ${fmt(m.uberTarget)} · logrado ${fmt(m.uber)}`)}</div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Peso de ingresos</h2><span class="pill">${state.selectedMonth}</span></div>${bars([['Trabajo',m.work],['DEBITAR',m.debitar],['Uber',m.uber],['Otros',m.other]],m.income,true)}</div><div class="card"><div class="section"><h2>Uso del tiempo</h2><span class="pill">${num(time)} h</span></div>${bars([['Trabajo',m.workHours],['DEBITAR',m.debHours],['Uber',m.uberHours]],time,false,' h')}</div></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Rentabilidad por hora</h2></div>${[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]].map(x=>`<div class="split" style="padding:9px 0;border-bottom:1px solid #1b2d43"><span>${x[0]}</span><b>${x[2]?fmt(x[1]/x[2])+'/h':'—'}</b></div>`).join('')}</div><div class="card"><div class="section"><h2>DEBITAR</h2></div><div class="big">${fmt(m.debitar)} <span class="muted" style="font-size:13px">cobrado</span></div><p class="muted">Cartera mensual activa: ${fmt(m.expectedDebitar)} · ${num(m.debHours)} h trabajadas.</p><button class="btn ghost" data-go="DEBITAR">Ver clientes y cobranza</button></div></div>`}
function bars(rows,total,money,suf=''){return rows.map(r=>`<div class="chartrow"><span>${r[0]}</span><div class="bar"><i style="width:${Math.min(100,pct(r[1],total))}%"></i></div><b style="text-align:right">${money?fmt(r[1]):num(r[1])+suf}<br><small class="muted">${pct(r[1],total)}%</small></b></div>`).join('')}
function finances(){let ins=incomesM(),ws=state.wallets;return `<div class="actions"><button class="btn" data-act="income">+ Ingresar dinero</button><button class="btn ghost" data-act="transfer">Transferir entre cuentas</button></div><div class="grid three" style="margin-top:14px">${ws.map(w=>`<div class="card"><span class="pill">${esc(w.type)}</span><h3>${esc(w.name)}</h3><div class="big">${fmt(w.balance)}</div><small class="muted">${w.active?'Activa':'Inactiva'}</small></div>`).join('')}</div><div class="section"><h2>Ingresos manuales del mes</h2></div><div class="card">${ins.length?table(['Fecha','Fuente','Monto','Billetera','Nota'],ins.map(i=>[i.date,i.source,fmt(i.amount),walletName(i.wallet),i.note||''])):'<div class="empty">Los cobros DEBITAR y turnos Uber llegan automáticamente. Aquí registra principalmente sueldo u otras fuentes.</div>'}</div>`}
function expenses(){let ex=monthExpenses(),m=metrics();return `<div class="grid three">${kpi('Total del mes',fmt(m.recurring),'Gastos recurrentes')}${kpi('Pagado',fmt(ex.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0)),'Sólo gastos recurrentes')}${kpi('Por pagar',fmt(ex.filter(e=>e.status!=='Pagado').reduce((a,e)=>a+e.amount,0)),'Pendiente')}</div><div class="section"><h2>Listado de gastos</h2><button class="btn" data-act="newexpense">+ Nuevo gasto</button></div><div class="card"><table><thead><tr><th>Concepto</th><th>Categoría</th><th>Día</th><th>Monto mes</th><th>Estado</th><th></th></tr></thead><tbody>${ex.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(e.category)}</td><td>${e.day}</td><td class="num"><button class="btn ghost sm" data-edit-exp="${e.id}">${fmt(e.amount)}</button></td><td>${e.status==='Pagado'?'<span class="pill ok">Pagado</span>':'<span class="pill wait">Pendiente</span>'}</td><td>${e.status==='Pagado'?`<small>${esc(walletName(e.wallet))}</small>`:`<button class="btn sm" data-pay-exp="${e.id}">Marcar pagado</button>`}</td></tr>`).join('')}</tbody></table></div><div class="notice">Las cuotas del módulo Deudas se suman al flujo del mes, pero no se duplican dentro de este listado.</div>`}
function debts(){let ds=debtsM(),sum=ds.reduce((a,d)=>a+d.amount,0),paid=ds.filter(d=>d.status==='Pagada').reduce((a,d)=>a+d.amount,0);return `<div class="grid three">${kpi('Cuotas del mes',fmt(sum))}${kpi('Pagadas',fmt(paid))}${kpi('Pendientes',fmt(sum-paid))}</div><div class="section"><h2>Calendario de deudas</h2><button class="btn" data-act="newdebt">+ Agregar cuota</button></div><div class="card">${ds.length?`<table><thead><tr><th>Fecha</th><th>Acreedor</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td>${d.date}</td><td>${esc(d.name)}</td><td class="num">${fmt(d.amount)}</td><td><span class="pill ${d.status==='Pagada'?'ok':'wait'}">${d.status}</span></td><td>${d.status==='Pagada'?'':`<button class="btn sm" data-pay-debt="${d.id}">Pagar</button>`}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Sin cuotas este mes.</div>'}</div>`}
function debitar(){let m=metrics(),cols=collectionsM();return `<div class="grid kpis">${kpi('Cartera activa',fmt(m.expectedDebitar))}${kpi('Cobrado mes',fmt(m.debitar))}${kpi('Pendiente cartera',fmt(Math.max(0,m.expectedDebitar-m.debitar)))}${kpi('Horas DEBITAR',num(m.debHours)+' h',m.debHours?fmt(m.debitar/m.debHours)+'/h':'Sin horas registradas')}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="startdebitar">▶ Iniciar trabajo DEBITAR</button><button class="btn ghost" data-act="manualdebitar">+ Registrar horas</button><button class="btn ghost" data-act="newclient">+ Cliente</button><button class="btn ghost" data-act="newprospect">+ Prospecto</button></div><div class="section"><h2>Clientes</h2></div><div class="card"><table><thead><tr><th>Cliente</th><th>RUT</th><th>Valor</th><th>Día</th><th>Estado mes</th><th></th></tr></thead><tbody>${state.clients.filter(c=>c.active).map(c=>{let co=cols.find(x=>x.clientId===c.id);return `<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.rut||'—')}</td><td class="num">${fmt(c.fee)}</td><td>${c.day}</td><td>${co?.status==='Cobrado'?'<span class="pill ok">Cobrado</span>':'<span class="pill wait">Pendiente</span>'}</td><td class="actions"><button class="btn ghost sm" data-client="${c.id}">Abrir ficha</button>${co?.status==='Cobrado'?'':`<button class="btn sm" data-collect="${c.id}">Registrar cobro</button>`}</td></tr>`}).join('')}</tbody></table></div>`}
function uber(){let ts=turnsM(),m=metrics(),avgH=m.uberHours?m.uber/m.uberHours:0;return `<div class="grid kpis">${kpi('Meta Uber calculada',fmt(m.uberTarget),'Brecha del ecosistema')}${kpi('Neto económico acumulado',fmt(m.uber))}${kpi('Falta cubrir',fmt(m.uberMissing),avgH&&m.uberMissing?`≈ ${num(m.uberMissing/avgH)} h al ritmo actual`:'')}${kpi('Horas Uber',num(m.uberHours)+' h',avgH?fmt(avgH)+'/h':'')}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="newturn">+ Nuevo turno</button><button class="btn ghost" data-act="ubersettings">Ajustes Uber</button></div><div class="notice"><b>Dos lecturas distintas:</b> la billetera recibe el excedente de caja del turno (bruto − bencina cargada). El resultado Uber usa neto económico (bruto − combustible consumido − desgaste − retención). Así no confundimos caja con rentabilidad.</div><div class="section"><h2>Historial del mes</h2></div><div class="card">${ts.length?`<table><thead><tr><th>Fecha</th><th>Horas</th><th>Km</th><th>Bruto</th><th>Bencina cargada</th><th>Excedente caja</th><th>Neto económico</th><th>$/h</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${t.start.slice(0,10)}</td><td>${num(t.hours)}</td><td>${num(t.km)}</td><td class="num">${fmt(t.gross)}</td><td class="num">${fmt(t.fuelLoad)}</td><td class="num">${fmt(t.cashSurplus)}</td><td class="num"><b>${fmt(t.net)}</b></td><td class="num">${t.hours?fmt(t.net/t.hours):'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Aún no hay turnos registrados en este mes.</div>'}</div>`}
function objectives(){return `<div class="grid two">${state.objectives.map((o,i)=>`<div class="card"><div class="split"><div><small class="muted">OBJETIVO</small><h3>${esc(o.name)}</h3></div><button class="btn ghost sm" data-obj="${i}">Editar</button></div><div class="big">${fmt(o.current)} / ${fmt(o.target)}</div><div class="bar" style="margin-top:12px"><i style="width:${Math.min(100,pct(o.current,o.target))}%"></i></div><p class="muted">Avance ${pct(o.current,o.target)}%</p></div>`).join('')}</div>`}
function allMonths(){let s=new Set([state.selectedMonth]);state.incomes.forEach(x=>s.add(ym(x.date)));state.uberTurns.forEach(x=>s.add(ym(x.start)));state.collections.forEach(x=>s.add(x.month));state.debts.forEach(x=>s.add(ym(x.date)));return [...s].filter(Boolean).sort()}function reports(){let months=allMonths();return `<div class="section"><h2>Resultados por mes</h2></div><div class="card"><table><thead><tr><th>Mes</th><th>Trabajo</th><th>DEBITAR</th><th>Uber</th><th>Otros</th><th>Ingresos</th><th>Obligaciones</th><th>Resultado</th></tr></thead><tbody>${months.map(x=>{let m=metrics(x);return `<tr><td><b>${x}</b></td><td class="num">${fmt(m.work)}</td><td class="num">${fmt(m.debitar)}</td><td class="num">${fmt(m.uber)}</td><td class="num">${fmt(m.other)}</td><td class="num">${fmt(m.income)}</td><td class="num">${fmt(m.due)}</td><td class="num ${m.result>=0?'positive':'negative'}"><b>${fmt(m.result)}</b></td></tr>`}).join('')}</tbody></table></div><div class="section"><h2>Flujo de caja · mes seleccionado</h2></div><div class="grid three">${kpi('Entradas económicas',fmt(metrics().income))}${kpi('Salidas / obligaciones',fmt(metrics().due))}${kpi('Flujo neto',fmt(metrics().result))}</div>`}
function settings(){return `<div class="grid two"><div class="card"><h3>Configuración general</h3><div class="field"><label>Horas mensuales trabajo dependiente</label><input id="workHours" type="number" value="${state.workSettings.monthlyHours}"></div><button class="btn" data-act="savegeneral" style="margin-top:10px">Guardar</button></div><div class="card"><h3>Respaldo</h3><p class="muted">Los datos siguen guardándose localmente en este dispositivo.</p><div class="actions"><button class="btn ghost" data-act="export">Exportar JSON</button><label class="btn ghost">Importar JSON<input id="import" type="file" accept="application/json" hidden></label></div></div></div>`}
function table(h,rows){return `<table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>`<td class="${i===2?'num':''}">${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}function walletName(id){return state.wallets.find(w=>w.id===id)?.name||'—'}function walletOptions(){return state.wallets.filter(w=>w.active).map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}
function bind(){$$('[data-go]').forEach(x=>x.onclick=()=>{page=x.dataset.go;shell()});$$('[data-act]').forEach(x=>x.onclick=()=>action(x.dataset.act));$$('[data-client]').forEach(x=>x.onclick=()=>clientModal(x.dataset.client));$$('[data-collect]').forEach(x=>x.onclick=()=>collectModal(x.dataset.collect));$$('[data-pay-exp]').forEach(x=>x.onclick=()=>payExpense(x.dataset.payExp));$$('[data-edit-exp]').forEach(x=>x.onclick=()=>editExpense(x.dataset.editExp));$$('[data-pay-debt]').forEach(x=>x.onclick=()=>payDebt(x.dataset.payDebt));$$('[data-obj]').forEach(x=>x.onclick=()=>objectiveModal(+x.dataset.obj));let imp=$('#import');if(imp)imp.onchange=importData}
function action(a){({income:incomeModal,transfer:transferModal,newexpense:()=>expenseModal(),newdebt:debtModal,newclient:()=>clientModal(),newtask:()=>taskModal(),newprospect:()=>prospectModal(),newturn:turnModal,ubersettings:uberSettingsModal,startdebitar:startDebitar,manualdebitar:manualDebitar,export:exportData,savegeneral:()=>{state.workSettings.monthlyHours=+$('#workHours').value||0;save('Configuración guardada');render()}}[a]||(()=>{}))()}
function modal(html,cb){let b=document.createElement('div');b.className='modal-bg';b.innerHTML=`<div class="modal"><div class="modal-head"><h2>Centro de Operaciones</h2><button class="close">×</button></div>${html}</div>`;document.body.appendChild(b);$('.close',b).onclick=()=>b.remove();b.onclick=e=>{if(e.target===b)b.remove()};cb&&cb(b)}
function incomeModal(){modal(`<div class="form-grid"><div class="field"><label>Fecha</label><input id="iDate" type="date" value="${state.selectedMonth}-01"></div><div class="field"><label>Fuente</label><select id="iSource"><option>Trabajo dependiente</option><option>Otro emprendimiento</option><option>Otro ingreso</option></select></div><div class="field"><label>Monto líquido</label><input id="iAmount" type="number"></div><div class="field"><label>Billetera destino</label><select id="iWallet">${walletOptions()}</select></div><div class="field"><label>Nota</label><input id="iNote"></div></div><button class="btn" id="iSave" style="margin-top:12px">Registrar ingreso</button>`,b=>$('#iSave',b).onclick=()=>{let a=+$('#iAmount',b).value||0,w=$('#iWallet',b).value;if(a<=0)return alert('Ingresa un monto');state.incomes.push({id:uid('i'),date:$('#iDate',b).value,source:$('#iSource',b).value,amount:a,wallet:w,note:$('#iNote',b).value});let ww=state.wallets.find(x=>x.id===w);if(ww)ww.balance+=a;save('Ingreso registrado');b.remove();render()})}
function transferModal(){modal(`<div class="form-grid"><div class="field"><label>Desde</label><select id="f">${walletOptions()}</select></div><div class="field"><label>Hacia</label><select id="t">${walletOptions()}</select></div><div class="field"><label>Monto</label><input id="a" type="number"></div></div><button class="btn" id="s">Transferir</button>`,b=>$('#s',b).onclick=()=>{let f=state.wallets.find(w=>w.id===$('#f',b).value),t=state.wallets.find(w=>w.id===$('#t',b).value),a=+$('#a',b).value||0;if(!f||!t||f===t||a<=0)return alert('Revisa los datos');f.balance-=a;t.balance+=a;state.transfers.push({id:uid('tr'),date:new Date().toISOString(),from:f.id,to:t.id,amount:a});save('Transferencia: no afecta resultado');b.remove();render()})}
function expenseModal(){modal(`<div class="form-grid"><div class="field"><label>Concepto</label><input id="n"></div><div class="field"><label>Categoría</label><input id="c"></div><div class="field"><label>Monto base</label><input id="a" type="number"></div><div class="field"><label>Día de pago</label><input id="d" type="number" min="1" max="31"></div></div><button class="btn" id="s">Guardar gasto recurrente</button>`,b=>$('#s',b).onclick=()=>{state.expenseTemplates.push({id:uid('e'),name:$('#n',b).value,category:$('#c',b).value,amount:+$('#a',b).value||0,day:+$('#d',b).value||1,active:true});save();b.remove();render()})}function editExpense(id){let e=monthExpenses().find(x=>x.id===id);modal(`<div class="field"><label>Monto para ${state.selectedMonth}</label><input id="a" type="number" value="${e.amount}"></div><button class="btn" id="s">Guardar monto del mes</button>`,b=>$('#s',b).onclick=()=>{state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...(state.expenseMonths[state.selectedMonth][id]||{}),amount:+$('#a',b).value||0};save('Monto mensual actualizado');b.remove();render()})}function payExpense(id){let e=monthExpenses().find(x=>x.id===id);modal(`<div class="form-grid"><div class="field"><label>Monto pagado</label><input id="a" type="number" value="${e.amount}"></div><div class="field"><label>Billetera</label><select id="w">${walletOptions()}</select></div><div class="field"><label>Fecha pago</label><input id="d" type="date" value="${state.selectedMonth}-${String(Math.min(e.day,28)).padStart(2,'0')}"></div></div><button class="btn" id="s">Confirmar pago</button>`,b=>$('#s',b).onclick=()=>{let a=+$('#a',b).value||0,w=$('#w',b).value;state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...(state.expenseMonths[state.selectedMonth][id]||{}),status:'Pagado',paidAmount:a,wallet:w,paidDate:$('#d',b).value};let ww=state.wallets.find(x=>x.id===w);if(ww)ww.balance-=a;save('Gasto marcado pagado');b.remove();render()})}
function debtModal(){modal(`<div class="form-grid"><div class="field"><label>Acreedor</label><input id="n"></div><div class="field"><label>Fecha</label><input id="d" type="date"></div><div class="field"><label>Monto</label><input id="a" type="number"></div></div><button class="btn" id="s">Guardar cuota</button>`,b=>$('#s',b).onclick=()=>{state.debts.push({id:uid('d'),name:$('#n',b).value,date:$('#d',b).value,amount:+$('#a',b).value||0,status:'Pendiente'});save();b.remove();render()})}function payDebt(id){let d=state.debts.find(x=>x.id===id);modal(`<div class="field"><label>Billetera</label><select id="w">${walletOptions()}</select></div><button class="btn" id="s">Confirmar pago ${fmt(d.amount)}</button>`,b=>$('#s',b).onclick=()=>{d.status='Pagada';d.wallet=$('#w',b).value;d.paidDate=new Date().toISOString().slice(0,10);let w=state.wallets.find(x=>x.id===d.wallet);if(w)w.balance-=d.amount;save('Cuota pagada');b.remove();render()})}
async function getMaster(){if(vaultSession)return vaultSession;let p=prompt('Contraseña maestra de la bóveda (no se guarda):');if(!p)throw Error('Se requiere contraseña');vaultSession=p;return p}async function deriveKey(p,s){let e=new TextEncoder(),base=await crypto.subtle.importKey('raw',e.encode(p),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:150000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}const b64=a=>btoa(String.fromCharCode(...new Uint8Array(a))),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));async function encryptSecrets(o){let p=await getMaster(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(p,salt),ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(o)));return{salt:b64(salt),iv:b64(iv),ct:b64(ct)}}async function decrypt(v){if(!v)return{sii:'',previred:'',mutual:'',dt:''};try{let key=await deriveKey(await getMaster(),unb64(v.salt)),pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(v.iv)},key,unb64(v.ct));return JSON.parse(new TextDecoder().decode(pt))}catch{vaultSession=null;throw Error('Clave maestra incorrecta')}}
function clientModal(id){let idx=state.clients.findIndex(x=>x.id===id),c=idx>=0?state.clients[idx]:{id:uid('c'),rut:'',name:'',reps:[],fee:0,day:1,email:'',phone:'',vault:null,active:true};modal(`<div class="form-grid"><div class="field"><label>RUT</label><input id="rut" value="${esc(c.rut)}"></div><div class="field"><label>Nombre / razón social</label><input id="name" value="${esc(c.name)}"></div><div class="field"><label>Representantes legales (separados por coma)</label><input id="reps" value="${esc(c.reps.map(x=>x.name).join(', '))}"></div><div class="field"><label>RUT representantes (mismo orden)</label><input id="rr" value="${esc(c.reps.map(x=>x.rut).join(', '))}"></div><div class="field"><label>Valor que cobro</label><input id="fee" type="number" value="${c.fee}"></div><div class="field"><label>Día cobro</label><input id="day" type="number" value="${c.day}"></div><div class="field"><label>Correo</label><input id="email" value="${esc(c.email)}"></div><div class="field"><label>Número contacto</label><input id="phone" value="${esc(c.phone)}"></div></div><div class="section"><h2>Accesos protegidos</h2><button class="btn ghost sm" id="unlock">Mostrar / desbloquear</button></div><div class="form-grid" id="access"><div class="field"><label>Clave SII</label><input id="sii" type="password"></div><div class="field"><label>Clave Previred</label><input id="previred" type="password"></div><div class="field"><label>Clave Mutual</label><input id="mutual" type="password"></div><div class="field"><label>Clave DT</label><input id="dt" type="password"></div></div><button class="btn" id="save" style="margin-top:14px">Guardar ficha</button>`,b=>{$('#unlock',b).onclick=async()=>{try{let s=await decrypt(c.vault);['sii','previred','mutual','dt'].forEach(k=>$('#'+k,b).value=s[k]||'');$$('#access input',b).forEach(x=>x.type='text')}catch(e){alert(e.message)}};$('#save',b).onclick=async()=>{c.rut=$('#rut',b).value;c.name=$('#name',b).value;c.fee=+$('#fee',b).value||0;c.day=+$('#day',b).value||1;c.email=$('#email',b).value;c.phone=$('#phone',b).value;let ns=$('#reps',b).value.split(',').map(x=>x.trim()).filter(Boolean),rs=$('#rr',b).value.split(',').map(x=>x.trim());c.reps=ns.map((n,i)=>({name:n,rut:rs[i]||''}));let sec={sii:$('#sii',b).value,previred:$('#previred',b).value,mutual:$('#mutual',b).value,dt:$('#dt',b).value};if(Object.values(sec).some(Boolean))try{c.vault=await encryptSecrets(sec)}catch(e){return alert(e.message)};idx<0?state.clients.push(c):state.clients[idx]=c;save('Ficha guardada');b.remove();render()}})}
function collectModal(id){let c=state.clients.find(x=>x.id===id);modal(`<div class="form-grid"><div class="field"><label>Monto cobrado</label><input id="a" type="number" value="${c.fee}"></div><div class="field"><label>Fecha</label><input id="d" type="date" value="${state.selectedMonth}-${String(Math.min(c.day,28)).padStart(2,'0')}"></div><div class="field"><label>Billetera destino</label><select id="w">${walletOptions()}</select></div></div><button class="btn" id="s">Registrar cobro</button>`,b=>$('#s',b).onclick=()=>{let a=+$('#a',b).value||0,w=$('#w',b).value;state.collections.push({id:uid('co'),clientId:id,month:state.selectedMonth,date:$('#d',b).value,amount:a,wallet:w,status:'Cobrado'});let ww=state.wallets.find(x=>x.id===w);if(ww)ww.balance+=a;save('Cobro DEBITAR registrado');b.remove();render()})}
function startDebitar(){let start=new Date(),pending=(state.tasks||[]).filter(t=>t.status!=='Hecha');modal(`<div class="field"><label>Tarea asociada (opcional)</label><select id="task"><option value="">Trabajo general DEBITAR</option>${pending.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></div><p>Sesión iniciada: <b>${start.toLocaleTimeString('es-CL')}</b></p><p class="muted">Al finalizar, las horas quedarán asociadas a la tarea seleccionada.</p><button class="btn" id="stop">■ Finalizar sesión</button>`,b=>$('#stop',b).onclick=()=>{let end=new Date(),hours=(end-start)/36e5,taskId=$('#task',b).value;state.debitarSessions.push({id:uid('ds'),start:start.toISOString(),end:end.toISOString(),hours,taskId});if(taskId){let t=state.tasks.find(x=>x.id===taskId);if(t)t.hours=(+t.hours||0)+hours}save('Sesión DEBITAR: '+num(hours)+' h');b.remove();render()})}function manualDebitar(){modal(`<div class="form-grid"><div class="field"><label>Fecha</label><input id="d" type="date" value="${state.selectedMonth}-01"></div><div class="field"><label>Horas</label><input id="h" type="number" step="0.25"></div></div><button class="btn" id="s">Registrar</button>`,b=>$('#s',b).onclick=()=>{let d=$('#d',b).value,h=+$('#h',b).value||0;state.debitarSessions.push({id:uid('ds'),start:d+'T12:00:00',end:d+'T12:00:00',hours:h,manual:true});save();b.remove();render()})}
function turnModal(){modal(`<div class="form-grid three"><div class="field"><label>Inicio</label><input id="st" type="datetime-local"></div><div class="field"><label>Fin</label><input id="en" type="datetime-local"></div><div class="field"><label>Km tablero inicio</label><input id="o1" type="number" step="0.1"></div><div class="field"><label>Km tablero fin</label><input id="o2" type="number" step="0.1"></div><div class="field"><label>Ingreso app/tarjeta</label><input id="card" type="number"></div><div class="field"><label>Efectivo</label><input id="cash" type="number"></div><div class="field"><label>Propinas / otros</label><input id="tips" type="number"></div><div class="field"><label>Bencina cargada en turno</label><input id="load" type="number"></div><div class="field"><label>Billetera para excedente</label><select id="w">${walletOptions()}</select></div></div><div id="preview" class="notice">Completa los datos y guarda. El sistema separará caja y rentabilidad.</div><button class="btn" id="s" style="margin-top:12px">Cerrar y guardar turno</button>`,b=>$('#s',b).onclick=()=>{let st=$('#st',b).value,en=$('#en',b).value,o1=+$('#o1',b).value,o2=+$('#o2',b).value;if(!st||!en||o2<o1)return alert('Revisa horario y kilometraje');let hours=(new Date(en)-new Date(st))/36e5,km=o2-o1,gross=(+$('#card',b).value||0)+(+$('#cash',b).value||0)+(+$('#tips',b).value||0),load=+$('#load',b).value||0,s=state.uberSettings,fuel=s.efficiency>0?km/s.efficiency*s.fuelPrice:0,wear=km*s.wearKm,ret=gross*s.retention/100,net=gross-fuel-wear-ret,cashSurplus=gross-load,w=$('#w',b).value;state.uberTurns.push({id:uid('u'),start:st,end:en,odo1:o1,odo2:o2,km,hours,gross,card:+$('#card',b).value||0,cash:+$('#cash',b).value||0,tips:+$('#tips',b).value||0,fuelLoad:load,fuelCost:fuel,wear,retention:ret,net,cashSurplus,wallet:w});let ww=state.wallets.find(x=>x.id===w);if(ww)ww.balance+=cashSurplus;save(`Turno: caja ${fmt(cashSurplus)} · neto ${fmt(net)}`);b.remove();render()})}
function uberSettingsModal(){let s=state.uberSettings;modal(`<div class="form-grid"><div class="field"><label>Precio bencina $/litro</label><input id="p" type="number" value="${s.fuelPrice}"></div><div class="field"><label>Rendimiento km/l</label><input id="e" type="number" step="0.1" value="${s.efficiency}"></div><div class="field"><label>Desgaste / mantención $ por km</label><input id="w" type="number" value="${s.wearKm}"></div><div class="field"><label>Retención / reserva %</label><input id="r" type="number" step="0.1" value="${s.retention}"></div><div class="field"><label>Capital habitual de salida</label><input id="c" type="number" value="${s.startCapital}"></div></div><button class="btn" id="s">Guardar ajustes</button>`,b=>$('#s',b).onclick=()=>{state.uberSettings={fuelPrice:+$('#p',b).value||0,efficiency:+$('#e',b).value||0,wearKm:+$('#w',b).value||0,retention:+$('#r',b).value||0,startCapital:+$('#c',b).value||0};save();b.remove();render()})}
function objectiveModal(i){let o=state.objectives[i];modal(`<div class="form-grid"><div class="field"><label>Objetivo</label><input id="n" value="${esc(o.name)}"></div><div class="field"><label>Meta</label><input id="t" type="number" value="${o.target}"></div><div class="field"><label>Acumulado</label><input id="c" type="number" value="${o.current}"></div></div><button class="btn" id="s">Guardar</button>`,b=>$('#s',b).onclick=()=>{o.name=$('#n',b).value;o.target=+$('#t',b).value||0;o.current=+$('#c',b).value||0;save();b.remove();render()})}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='debitar-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)}function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{state=Object.assign(clone(seed),JSON.parse(r.result));save('Respaldo importado');render()}catch{alert('Respaldo inválido')}};r.readAsText(f)}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
// ===== v0.4: motor operativo ampliado =====
function incomeSourceLabel(s){return s||'Otro ingreso'}
function dashboard(){let m=metrics(),time=m.workHours+m.debHours+m.uberHours,totalWallet=state.wallets.reduce((a,w)=>a+(+w.balance||0),0),ex=monthExpenses(),exPaid=ex.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0),debtPaid=debtsM().filter(d=>d.status==='Pagada').reduce((a,d)=>a+d.amount,0);let next=state.clients.filter(c=>c.active&&!collectionsM().some(x=>x.clientId===c.id&&x.status==='Cobrado')).sort((a,b)=>a.day-b.day).slice(0,5);return `<div class="hero"><div><span class="eyebrow">CENTRO DE OPERACIONES · ${state.selectedMonth}</span><h2>Control hoy. Decisiones con datos mañana.</h2><p>Tu sueldo, DEBITAR, Uber, gastos, deudas y objetivos en un solo ecosistema.</p></div><div class="hero-number"><small>Resultado del mes</small><b class="${m.result>=0?'positive':'negative'}">${fmt(m.result)}</b><span>${m.result>=0?'superávit proyectado':'déficit por cubrir'}</span></div></div><div class="grid dash5">${kpi('Ingresos del mes',fmt(m.income),`Trabajo ${fmt(m.work)} · DEBITAR ${fmt(m.debitar)} · Uber ${fmt(m.uber)}`)}${kpi('Gastos del mes',fmt(m.recurring),`Pagado ${fmt(exPaid)} · pendiente ${fmt(Math.max(0,m.recurring-exPaid))}`)}${kpi('Cuotas deudas',fmt(m.debtDue),`Pagadas ${fmt(debtPaid)}`)}${kpi('Saldo billeteras',fmt(totalWallet),'Disponibilidad registrada')}${kpi('Meta Uber faltante',fmt(m.uberMissing),`Meta ${fmt(m.uberTarget)}`)}</div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Ingresos por fuente</h2><span class="pill">peso mensual</span></div>${bars([['Trabajo',m.work],['DEBITAR',m.debitar],['Uber',m.uber],['Otros',m.other]],m.income,true)}</div><div class="card"><div class="section"><h2>Tiempo y productividad</h2><span class="pill">${num(time)} h</span></div>${[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]].map(x=>`<div class="productivity"><div><b>${x[0]}</b><small>${num(x[2])} h · ${pct(x[2],time)}% del tiempo</small></div><strong>${x[2]?fmt(x[1]/x[2])+'/h':'—'}</strong></div>`).join('')}</div></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Próximos cobros DEBITAR</h2><button class="linkbtn" data-go="DEBITAR">Ver clientes</button></div>${next.length?next.map(c=>`<div class="split line"><span><b>Día ${c.day}</b> · ${esc(c.name)}</span><b>${fmt(c.fee)}</b></div>`).join(''):'<div class="empty">No hay cobros pendientes del mes.</div>'}</div><div class="card"><div class="section"><h2>Objetivos</h2><button class="linkbtn" data-go="Objetivos">Gestionar</button></div>${state.objectives.map(o=>`<div class="goalmini"><div class="split"><span>${esc(o.name)}</span><b>${pct(o.current,o.target)}%</b></div><div class="bar"><i style="width:${Math.min(100,pct(o.current,o.target))}%"></i></div><small>${fmt(o.current)} de ${fmt(o.target)}</small></div>`).join('')}</div></div>`}
function finances(){let ins=incomesM(),ws=state.wallets;return `<div class="actions"><button class="btn" data-act="income">+ Registrar ingreso</button><button class="btn ghost" data-act="transfer">↔ Transferir</button></div><div class="grid three" style="margin-top:14px">${ws.map(w=>`<div class="card wallet"><span class="pill">${esc(w.type)}</span><h3>${esc(w.name)}</h3><div class="big">${fmt(w.balance)}</div><small class="muted">${w.active?'Activa':'Inactiva'}</small></div>`).join('')}</div><div class="section"><h2>Ingresos registrados · ${state.selectedMonth}</h2></div><div class="card">${ins.length?`<table><thead><tr><th>Fecha</th><th>Fuente</th><th>Monto</th><th>Billetera</th><th>Nota</th><th></th></tr></thead><tbody>${ins.map(i=>`<tr><td>${i.date}</td><td>${esc(i.source)}</td><td class="num">${fmt(i.amount)}</td><td>${esc(walletName(i.wallet))}</td><td>${esc(i.note||'')}</td><td><button class="btn ghost sm" data-edit-income="${i.id}">Editar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Registra aquí tu sueldo líquido y otras entradas manuales. DEBITAR y Uber alimentan el ecosistema automáticamente.</div>'}</div>`}
function expenses(){let ex=monthExpenses(),paid=ex.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0),total=ex.reduce((a,e)=>a+e.amount,0);return `<div class="grid three">${kpi('Total gastos',fmt(total),'Presupuesto del mes')}${kpi('Pagado',fmt(paid),pct(paid,total)+'%')}${kpi('Por pagar',fmt(Math.max(0,total-paid)),'Pendiente')}</div><div class="section"><h2>Listado de gastos</h2><button class="btn" data-act="newexpense">+ Nuevo gasto</button></div><div class="card tablewrap"><table><thead><tr><th>Concepto</th><th>Categoría</th><th>Día</th><th>Monto</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${ex.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(e.category)}</td><td>${e.day}</td><td class="num"><button class="btn ghost sm" data-edit-exp="${e.id}">${fmt(e.amount)}</button></td><td>${e.status==='Pagado'?`<span class="pill ok">Pagado</span><small class="block">${esc(walletName(e.wallet))}</small>`:'<span class="pill wait">Pendiente</span>'}</td><td>${e.status==='Pagado'?`<button class="btn ghost sm" data-unpay-exp="${e.id}">↩ Volver a pendiente</button>`:`<button class="btn sm" data-pay-exp="${e.id}">Marcar pagado</button>`}</td></tr>`).join('')}</tbody></table></div><div class="notice">Las cuotas de Deudas se incorporan al flujo general, pero no se duplican como gasto recurrente.</div>`}
function debts(){let ds=debtsM(),sum=ds.reduce((a,d)=>a+d.amount,0),paid=ds.filter(d=>d.status==='Pagada').reduce((a,d)=>a+d.amount,0);return `<div class="grid three">${kpi('Cuotas del mes',fmt(sum))}${kpi('Pagadas',fmt(paid))}${kpi('Pendientes',fmt(sum-paid))}</div><div class="section"><h2>Calendario de deudas</h2><button class="btn" data-act="newdebt">+ Agregar cuota</button></div><div class="card">${ds.length?`<table><thead><tr><th>Fecha</th><th>Acreedor</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td>${d.date}</td><td>${esc(d.name)}</td><td class="num">${fmt(d.amount)}</td><td><span class="pill ${d.status==='Pagada'?'ok':'wait'}">${d.status}</span></td><td>${d.status==='Pagada'?`<button class="btn ghost sm" data-unpay-debt="${d.id}">↩ Volver a pendiente</button>`:`<button class="btn sm" data-pay-debt="${d.id}">Pagar</button>`}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Sin cuotas este mes.</div>'}</div>`}
function activeShift(){return state.uberActiveShift}
function activeTrips(){let a=activeShift();return a?state.uberTrips.filter(t=>t.shiftId===a.id):[]}
function uber(){let ts=turnsM(),m=metrics(),avgH=m.uberHours?m.uber/m.uberHours:0,a=activeShift(),tr=activeTrips(),tripGross=tr.reduce((x,t)=>x+t.amount,0),fuelLoad=a?+a.fuelLoad||0:0,recovered=Math.min(tripGross,fuelLoad),over=Math.max(0,tripGross-fuelLoad);return `<div class="grid kpis">${kpi('Meta Uber',fmt(m.uberTarget),'Brecha mensual')}${kpi('Neto acumulado',fmt(m.uber))}${kpi('Falta cubrir',fmt(m.uberMissing),avgH&&m.uberMissing?`≈ ${num(m.uberMissing/avgH)} h`:'')}${kpi('Horas cerradas',num(m.uberHours)+' h')}</div>${a?`<div class="shift-live"><div><span class="live-dot"></span><b> TURNO EN CURSO</b><small> iniciado ${new Date(a.start).toLocaleString('es-CL')}</small></div><div class="shift-stats"><span>Viajes <b>${tr.length}</b></span><span>Generado <b>${fmt(tripGross)}</b></span><span>Bencina a recuperar <b>${fmt(Math.max(0,fuelLoad-recovered))}</b></span><span>Excedente sobre carga <b>${fmt(over)}</b></span></div><div class="actions"><button class="btn" data-act="newtrip">+ Registrar viaje</button><button class="btn ghost" data-act="addfuel">+ Carga bencina</button><button class="btn danger" data-act="closeshift">Cerrar turno</button></div></div>`:`<div class="card startshift"><h3>¿Vas a salir a manejar?</h3><p class="muted">Inicia el turno y registra cada viaje a medida que ocurre. El acumulado se calcula solo.</p><button class="btn" data-act="startshift">▶ Iniciar turno Uber</button></div>`}<div class="actions" style="margin-top:14px"><button class="btn ghost" data-act="ubersettings">Ajustes Uber</button></div>${a?`<div class="section"><h2>Viajes del turno actual</h2></div><div class="card">${tr.length?`<table><thead><tr><th>Hora</th><th>Ingreso</th><th>Medio</th><th>Km viaje</th><th>Nota</th></tr></thead><tbody>${tr.map(t=>`<tr><td>${t.time}</td><td class="num">${fmt(t.amount)}</td><td>${esc(t.method)}</td><td>${num(t.km||0)}</td><td>${esc(t.note||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Aún no registras viajes en este turno.</div>'}</div>`:''}<div class="section"><h2>Turnos cerrados del mes</h2></div><div class="card">${ts.length?`<table><thead><tr><th>Fecha</th><th>Viajes</th><th>Horas</th><th>Km</th><th>Bruto</th><th>Combustible</th><th>Neto</th><th>$/h</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${t.start.slice(0,10)}</td><td>${t.tripCount||'—'}</td><td>${num(t.hours)}</td><td>${num(t.km)}</td><td class="num">${fmt(t.gross)}</td><td class="num">${fmt(t.fuelCost||0)}</td><td class="num"><b>${fmt(t.net)}</b></td><td class="num">${t.hours?fmt(t.net/t.hours):'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Aún no hay turnos cerrados este mes.</div>'}</div>`}
function objectives(){return `<div class="notice"><b>Cómo se alimentan:</b> usa “Abonar / actualizar” cuando reserves dinero para una meta. Puedes indicar en qué billetera está guardado; el abono no duplica ni descuenta el saldo, sólo identifica qué parte de tus fondos está destinada al objetivo.</div><div class="grid two" style="margin-top:14px">${state.objectives.map((o,i)=>`<div class="card"><div class="split"><div><small class="muted">OBJETIVO</small><h3>${esc(o.name)}</h3></div><button class="btn ghost sm" data-obj="${i}">Editar</button></div><div class="big">${fmt(o.current)} / ${fmt(o.target)}</div><div class="bar" style="margin-top:12px"><i style="width:${Math.min(100,pct(o.current,o.target))}%"></i></div><div class="split" style="margin-top:10px"><small class="muted">Avance ${pct(o.current,o.target)}%</small><button class="btn sm" data-contribute="${i}">+ Abonar / actualizar</button></div></div>`).join('')}</div><div class="section"><h2>Movimientos de objetivos</h2></div><div class="card">${(state.objectiveContributions||[]).length?`<table><thead><tr><th>Fecha</th><th>Objetivo</th><th>Monto</th><th>Ubicación</th></tr></thead><tbody>${state.objectiveContributions.slice().reverse().map(c=>`<tr><td>${c.date}</td><td>${esc(state.objectives[c.objective]?.name||'')}</td><td class="num">${fmt(c.amount)}</td><td>${esc(walletName(c.wallet))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no registras abonos a objetivos.</div>'}</div>`}
function reports(){let months=allMonths(),m=metrics();return `<div class="actions"><button class="btn" data-pdf="cash">PDF · Flujo de caja</button><button class="btn ghost" data-pdf="results">PDF · Resultados mensuales</button><button class="btn ghost" data-pdf="productivity">PDF · Ingresos y tiempo</button><button class="btn ghost" data-report="cash">CSV</button></div><div class="section"><h2>Resultados por mes</h2></div><div class="card tablewrap"><table><thead><tr><th>Mes</th><th>Trabajo</th><th>DEBITAR</th><th>Uber</th><th>Otros</th><th>Ingresos</th><th>Obligaciones</th><th>Resultado</th></tr></thead><tbody>${months.map(x=>{let z=metrics(x);return `<tr><td><b>${x}</b></td><td class="num">${fmt(z.work)}</td><td class="num">${fmt(z.debitar)}</td><td class="num">${fmt(z.uber)}</td><td class="num">${fmt(z.other)}</td><td class="num">${fmt(z.income)}</td><td class="num">${fmt(z.due)}</td><td class="num ${z.result>=0?'positive':'negative'}"><b>${fmt(z.result)}</b></td></tr>`}).join('')}</tbody></table></div><div class="section"><h2>Flujo de caja · ${state.selectedMonth}</h2></div><div class="grid three">${kpi('Entradas',fmt(m.income))}${kpi('Obligaciones',fmt(m.due))}${kpi('Resultado',fmt(m.result))}</div><div class="section"><h2>Productividad por fuente</h2></div><div class="card">${[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]].map(x=>`<div class="productivity"><div><b>${x[0]}</b><small>${num(x[2])} h · ${pct(x[1],m.income)}% del ingreso</small></div><strong>${x[2]?fmt(x[1]/x[2])+'/h':'—'}</strong></div>`).join('')}</div>`}
function bind(){$$('[data-go]').forEach(x=>x.onclick=()=>{page=x.dataset.go;shell()});$$('[data-act]').forEach(x=>x.onclick=()=>action(x.dataset.act));$$('[data-client]').forEach(x=>x.onclick=()=>clientModal(x.dataset.client));$$('[data-collect]').forEach(x=>x.onclick=()=>collectModal(x.dataset.collect));$$('[data-pay-exp]').forEach(x=>x.onclick=()=>payExpense(x.dataset.payExp));$$('[data-edit-exp]').forEach(x=>x.onclick=()=>editExpense(x.dataset.editExp));$$('[data-unpay-exp]').forEach(x=>x.onclick=()=>unpayExpense(x.dataset.unpayExp));$$('[data-pay-debt]').forEach(x=>x.onclick=()=>payDebt(x.dataset.payDebt));$$('[data-unpay-debt]').forEach(x=>x.onclick=()=>unpayDebt(x.dataset.unpayDebt));$$('[data-obj]').forEach(x=>x.onclick=()=>objectiveModal(+x.dataset.obj));$$('[data-contribute]').forEach(x=>x.onclick=()=>objectiveContribution(+x.dataset.contribute));$$('[data-edit-income]').forEach(x=>x.onclick=()=>editIncome(x.dataset.editIncome));$$('[data-report]').forEach(x=>x.onclick=()=>downloadReport(x.dataset.report));$$('[data-pdf]').forEach(x=>x.onclick=()=>printReport(x.dataset.pdf));$$('[data-task-toggle]').forEach(x=>x.onclick=()=>toggleTask(x.dataset.taskToggle));$$('[data-task-edit]').forEach(x=>x.onclick=()=>taskModal(x.dataset.taskEdit));$$('[data-prospect]').forEach(x=>x.onclick=()=>prospectModal(x.dataset.prospect));let imp=$('#import');if(imp)imp.onchange=importData}
function action(a){({income:incomeModal,transfer:transferModal,newexpense:()=>expenseModal(),newdebt:debtModal,newclient:()=>clientModal(),newtask:()=>taskModal(),newprospect:()=>prospectModal(),newturn:turnModal,ubersettings:uberSettingsModal,startdebitar:startDebitar,manualdebitar:manualDebitar,startshift:startUberShift,newtrip:newUberTrip,addfuel:addUberFuel,closeshift:closeUberShift,export:exportData,savegeneral:()=>{state.workSettings.monthlyHours=+$('#workHours').value||0;save('Configuración guardada');render()}}[a]||(()=>{}))()}
function editIncome(id){let i=state.incomes.find(x=>x.id===id);if(!i)return;modal(`<div class="form-grid"><div class="field"><label>Fecha</label><input id="d" type="date" value="${i.date}"></div><div class="field"><label>Fuente</label><select id="src"><option ${i.source==='Trabajo dependiente'?'selected':''}>Trabajo dependiente</option><option ${i.source==='Otro emprendimiento'?'selected':''}>Otro emprendimiento</option><option ${i.source==='Otro ingreso'?'selected':''}>Otro ingreso</option></select></div><div class="field"><label>Monto líquido</label><input id="a" type="number" value="${i.amount}"></div><div class="field"><label>Billetera</label><select id="w">${walletOptions()}</select></div><div class="field"><label>Nota</label><input id="n" value="${esc(i.note||'')}"></div></div><button class="btn" id="s">Guardar cambios</button>`,b=>{let wsel=$('#w',b);wsel.value=i.wallet;$('#s',b).onclick=()=>{let oldW=state.wallets.find(w=>w.id===i.wallet),newW=state.wallets.find(w=>w.id===wsel.value),old=+i.amount||0,nw=+$('#a',b).value||0;if(oldW)oldW.balance-=old;if(newW)newW.balance+=nw;i.date=$('#d',b).value;i.source=$('#src',b).value;i.amount=nw;i.wallet=wsel.value;i.note=$('#n',b).value;save('Ingreso actualizado');b.remove();render()}})}
function unpayExpense(id){let ov=(state.expenseMonths[state.selectedMonth]||{})[id];if(!ov||ov.status!=='Pagado')return;let w=state.wallets.find(x=>x.id===ov.wallet);if(w)w.balance+=(+ov.paidAmount||0);state.expenseMonths[state.selectedMonth][id]={...ov,status:'Pendiente',paidAmount:0,wallet:'',paidDate:''};save('Gasto vuelto a pendiente');render()}
function unpayDebt(id){let d=state.debts.find(x=>x.id===id);if(!d||d.status!=='Pagada')return;let w=state.wallets.find(x=>x.id===d.wallet);if(w)w.balance+=d.amount;d.status='Pendiente';d.wallet='';d.paidDate='';save('Cuota vuelta a pendiente');render()}
function startUberShift(){modal(`<div class="form-grid"><div class="field"><label>Inicio</label><input id="st" type="datetime-local" value="${new Date().toISOString().slice(0,16)}"></div><div class="field"><label>Km tablero inicio</label><input id="o" type="number" step="0.1"></div><div class="field"><label>Bencina cargada al iniciar</label><input id="f" type="number" value="0"></div><div class="field"><label>Billetera que recibirá el excedente</label><select id="w">${walletOptions()}</select></div></div><button class="btn" id="s">Iniciar turno</button>`,b=>$('#s',b).onclick=()=>{state.uberActiveShift={id:uid('us'),start:$('#st',b).value,odo1:+$('#o',b).value||0,fuelLoad:+$('#f',b).value||0,wallet:$('#w',b).value};save('Turno Uber iniciado');b.remove();render()})}
function newUberTrip(){let a=activeShift();if(!a)return alert('Primero inicia un turno');modal(`<div class="form-grid"><div class="field"><label>Hora</label><input id="t" type="time" value="${new Date().toTimeString().slice(0,5)}"></div><div class="field"><label>Ingreso del viaje</label><input id="a" type="number"></div><div class="field"><label>Medio</label><select id="m"><option>App / tarjeta</option><option>Efectivo</option><option>Otro</option></select></div><div class="field"><label>Km del viaje (opcional)</label><input id="k" type="number" step="0.1"></div><div class="field"><label>Nota / destino (opcional)</label><input id="n"></div></div><button class="btn" id="s">Guardar viaje</button>`,b=>$('#s',b).onclick=()=>{let amount=+$('#a',b).value||0;if(amount<=0)return alert('Ingresa el valor del viaje');state.uberTrips.push({id:uid('ut'),shiftId:a.id,date:a.start.slice(0,10),time:$('#t',b).value,amount,method:$('#m',b).value,km:+$('#k',b).value||0,note:$('#n',b).value});save('Viaje registrado');b.remove();render()})}
function addUberFuel(){let a=activeShift();if(!a)return;modal(`<div class="field"><label>Monto de la carga</label><input id="a" type="number"></div><button class="btn" id="s">Agregar carga</button>`,b=>$('#s',b).onclick=()=>{a.fuelLoad=(+a.fuelLoad||0)+(+$('#a',b).value||0);save('Carga agregada');b.remove();render()})}
function closeUberShift(){let a=activeShift(),tr=activeTrips();if(!a)return;modal(`<div class="form-grid"><div class="field"><label>Fin</label><input id="en" type="datetime-local" value="${new Date().toISOString().slice(0,16)}"></div><div class="field"><label>Km tablero final</label><input id="o" type="number" step="0.1"></div><div class="field"><label>Propinas / otros no registrados</label><input id="tips" type="number" value="0"></div></div><div class="notice">Viajes registrados: <b>${tr.length}</b> · generado: <b>${fmt(tr.reduce((x,t)=>x+t.amount,0))}</b> · carga bencina: <b>${fmt(a.fuelLoad||0)}</b>.</div><button class="btn" id="s">Cerrar y consolidar turno</button>`,b=>$('#s',b).onclick=()=>{let en=$('#en',b).value,o2=+$('#o',b).value||0;if(!en||o2<a.odo1)return alert('Revisa hora final y kilometraje');let hours=(new Date(en)-new Date(a.start))/36e5,km=o2-a.odo1,tips=+$('#tips',b).value||0,gross=tr.reduce((x,t)=>x+t.amount,0)+tips,s=state.uberSettings,fuel=s.efficiency>0?km/s.efficiency*s.fuelPrice:0,wear=km*s.wearKm,ret=gross*s.retention/100,net=gross-fuel-wear-ret,cashSurplus=gross-(+a.fuelLoad||0),ww=state.wallets.find(x=>x.id===a.wallet);state.uberTurns.push({id:a.id,start:a.start,end:en,odo1:a.odo1,odo2:o2,km,hours,gross,tips,fuelLoad:+a.fuelLoad||0,fuelCost:fuel,wear,retention:ret,net,cashSurplus,wallet:a.wallet,tripCount:tr.length});if(ww)ww.balance+=cashSurplus;state.uberActiveShift=null;save(`Turno cerrado · neto ${fmt(net)}`);b.remove();render()})}
function objectiveContribution(i){let o=state.objectives[i];modal(`<div class="form-grid"><div class="field"><label>Fecha</label><input id="d" type="date" value="${state.selectedMonth}-01"></div><div class="field"><label>Monto a sumar</label><input id="a" type="number"></div><div class="field"><label>¿Dónde está guardado?</label><select id="w">${walletOptions()}</select></div></div><p class="muted">Este registro no mueve dinero entre billeteras; sólo identifica fondos que ya tienes destinados a la meta.</p><button class="btn" id="s">Registrar abono</button>`,b=>$('#s',b).onclick=()=>{let a=+$('#a',b).value||0;if(!a)return;o.current=(+o.current||0)+a;state.objectiveContributions.push({id:uid('oc'),objective:i,date:$('#d',b).value,amount:a,wallet:$('#w',b).value});save('Objetivo actualizado');b.remove();render()})}
function csvDownload(name,rows){let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function downloadReport(type){let months=allMonths();if(type==='results')return csvDownload('resultados-mensuales.csv',[['Mes','Trabajo','DEBITAR','Uber','Otros','Ingresos','Obligaciones','Resultado'],...months.map(x=>{let m=metrics(x);return[x,m.work,m.debitar,m.uber,m.other,m.income,m.due,m.result]})]);if(type==='productivity')return csvDownload('ingresos-tiempo-'+state.selectedMonth+'.csv',[['Fuente','Ingreso','Horas','$/hora','% ingreso'],...(()=>{let m=metrics();return[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]].map(x=>[x[0],x[1],x[2],x[2]?Math.round(x[1]/x[2]):0,pct(x[1],m.income)])})()]);let m=metrics();return csvDownload('flujo-caja-'+state.selectedMonth+'.csv',[['Concepto','Monto'],['Ingresos trabajo',m.work],['Ingresos DEBITAR',m.debitar],['Ingresos Uber',m.uber],['Otros ingresos',m.other],['Total ingresos',m.income],['Gastos recurrentes',m.recurring],['Cuotas deudas',m.debtDue],['Total obligaciones',m.due],['Resultado',m.result]])}


function tasksPage(){let ts=(state.tasks||[]).slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));let pending=ts.filter(t=>t.status!=='Hecha'),done=ts.filter(t=>t.status==='Hecha');return `<div class="grid three">${kpi('Pendientes',pending.length)}${kpi('Completadas',done.length)}${kpi('Horas asociadas',num(ts.reduce((a,t)=>a+(+t.hours||0),0))+' h')}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="newtask">+ Nueva tarea</button></div><div class="section"><h2>Agenda de trabajo</h2></div><div class="card tablewrap">${ts.length?`<table><thead><tr><th>Estado</th><th>Tarea</th><th>Cliente / área</th><th>Vence</th><th>Prioridad</th><th>Horas</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><button class="btn ${t.status==='Hecha'?'ghost':''} sm" data-task-toggle="${t.id}">${t.status==='Hecha'?'✓ Hecha':'Pendiente'}</button></td><td><b>${esc(t.title)}</b><small class="muted block">${esc(t.note||'')}</small></td><td>${esc(t.client||'General')}</td><td>${t.due||'—'} ${t.time||''}</td><td><span class="pill ${t.priority==='Alta'?'bad':t.priority==='Media'?'wait':''}">${esc(t.priority||'Media')}</span></td><td>${num(t.hours||0)} h</td><td><button class="btn ghost sm" data-task-edit="${t.id}">Editar</button>${t.due?` <button class="btn ghost sm" onclick="openCalendarTask('${t.id}')">Calendar</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Crea tareas para clientes, DEBITAR o tu gestión personal. Luego puedes asociarlas a una sesión de trabajo.</div>'}</div>`}
function taskModal(id){let t=id?(state.tasks||[]).find(x=>x.id===id):null;let clients=state.clients.filter(c=>c.active);modal(`<div class="form-grid"><div class="field"><label>Tarea</label><input id="tt" value="${esc(t?.title||'')}"></div><div class="field"><label>Cliente / área</label><select id="cl"><option>General DEBITAR</option>${clients.map(c=>`<option ${t?.client===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}<option ${t?.client==='Personal'?'selected':''}>Personal</option></select></div><div class="field"><label>Fecha</label><input id="du" type="date" value="${t?.due||''}"></div><div class="field"><label>Hora recordatorio</label><input id="ti" type="time" value="${t?.time||''}"></div><div class="field"><label>Prioridad</label><select id="pr"><option ${t?.priority==='Alta'?'selected':''}>Alta</option><option ${!t||t?.priority==='Media'?'selected':''}>Media</option><option ${t?.priority==='Baja'?'selected':''}>Baja</option></select></div><div class="field"><label>Nota</label><input id="no" value="${esc(t?.note||'')}"></div></div><div class="actions"><button class="btn" id="sv">Guardar tarea</button><button class="btn ghost" id="cal">Guardar y abrir Google Calendar</button></div>`,b=>{let saveTask=()=>{let obj=t||{id:uid('task'),status:'Pendiente',hours:0};obj.title=$('#tt',b).value.trim();obj.client=$('#cl',b).value;obj.due=$('#du',b).value;obj.time=$('#ti',b).value;obj.priority=$('#pr',b).value;obj.note=$('#no',b).value;if(!obj.title)return alert('Escribe una tarea');if(!t)state.tasks.push(obj);save('Tarea guardada');return obj};$('#sv',b).onclick=()=>{if(saveTask()){b.remove();render()}};$('#cal',b).onclick=()=>{let x=saveTask();if(x){openCalendarTask(x.id);b.remove();render()}}})}
function toggleTask(id){let t=state.tasks.find(x=>x.id===id);if(!t)return;t.status=t.status==='Hecha'?'Pendiente':'Hecha';save('Estado de tarea actualizado');render()}
function openCalendarTask(id){let t=state.tasks.find(x=>x.id===id);if(!t||!t.due)return alert('La tarea necesita fecha');let st=t.due.replaceAll('-','')+(t.time?'T'+t.time.replace(':','')+'00':'');let en=st;if(t.time){let d=new Date(t.due+'T'+t.time+':00');d.setMinutes(d.getMinutes()+30);en=d.toISOString().replace(/[-:]/g,'').slice(0,15)}else{let d=new Date(t.due+'T12:00:00');d.setDate(d.getDate()+1);en=d.toISOString().slice(0,10).replaceAll('-','')}let url='https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(t.title)+'&details='+encodeURIComponent((t.client||'')+'\n'+(t.note||'')+'\nCreado desde Centro de Operaciones DEBITAR')+'&dates='+st+'/'+en;window.open(url,'_blank')}
function prospectModal(id){let p=id?(state.prospects||[]).find(x=>x.id===id):null;modal(`<div class="form-grid"><div class="field"><label>Prospecto</label><input id="n" value="${esc(p?.name||'')}"></div><div class="field"><label>Contacto</label><input id="c" value="${esc(p?.contact||'')}"></div><div class="field"><label>Valor potencial</label><input id="v" type="number" value="${p?.fee||0}"></div><div class="field"><label>Estado</label><select id="s"><option>Por contactar</option><option ${p?.status==='Contactado'?'selected':''}>Contactado</option><option ${p?.status==='Reunión'?'selected':''}>Reunión</option><option ${p?.status==='Propuesta'?'selected':''}>Propuesta</option><option ${p?.status==='Ganado'?'selected':''}>Ganado</option><option ${p?.status==='Descartado'?'selected':''}>Descartado</option></select></div><div class="field"><label>Próxima acción</label><input id="a" value="${esc(p?.next||'')}"></div></div><button class="btn" id="sv">Guardar prospecto</button>`,b=>$('#sv',b).onclick=()=>{let o=p||{id:uid('pr')};o.name=$('#n',b).value;o.contact=$('#c',b).value;o.fee=+$('#v',b).value||0;o.status=$('#s',b).value;o.next=$('#a',b).value;if(!p)state.prospects.push(o);save('Prospecto guardado');b.remove();render()})}
const debitarBase=debitar;debitar=function(){let html=debitarBase();let ps=state.prospects||[];let pipe=`<div class="section"><h2>Crecimiento de cartera</h2><button class="btn ghost sm" data-act="newprospect">+ Prospecto</button></div><div class="grid three">${kpi('Clientes activos',state.clients.filter(c=>c.active).length)}${kpi('Prospectos abiertos',ps.filter(p=>!['Ganado','Descartado'].includes(p.status)).length)}${kpi('Valor potencial',fmt(ps.filter(p=>!['Descartado'].includes(p.status)).reduce((a,p)=>a+(+p.fee||0),0)))}</div><div class="card tablewrap" style="margin-top:14px">${ps.length?`<table><thead><tr><th>Prospecto</th><th>Contacto</th><th>Valor</th><th>Estado</th><th>Próxima acción</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.contact||'—')}</td><td class="num">${fmt(p.fee)}</td><td><span class="pill">${esc(p.status)}</span></td><td>${esc(p.next||'—')}</td><td><button class="btn ghost sm" data-prospect="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Tu siguiente objetivo comercial es sumar al menos un cliente. Registra aquí los prospectos sin convertir el sistema en un CRM pesado.</div>'}</div>`;return html+pipe}
function reportLogo(){return document.querySelector('.logo')?.src||'https://danielmunoz-debitar.github.io/centro-operaciones/assets/logo-debitar.png'}
function printReport(type){let m=metrics(),months=allMonths(),title=type==='cash'?'Flujo de Caja':type==='results'?'Resultados Mensuales':'Ingresos, Tiempo y Productividad';let body='';if(type==='cash'){body=`<div class="summary"><div><small>Ingresos</small><b>${fmt(m.income)}</b></div><div><small>Obligaciones</small><b>${fmt(m.due)}</b></div><div><small>Resultado</small><b>${fmt(m.result)}</b></div></div><table><tr><th>Concepto</th><th>Monto</th></tr><tr><td>Trabajo dependiente</td><td>${fmt(m.work)}</td></tr><tr><td>DEBITAR</td><td>${fmt(m.debitar)}</td></tr><tr><td>Uber</td><td>${fmt(m.uber)}</td></tr><tr><td>Otros</td><td>${fmt(m.other)}</td></tr><tr><td>Total ingresos</td><td><b>${fmt(m.income)}</b></td></tr><tr><td>Gastos recurrentes</td><td>${fmt(m.recurring)}</td></tr><tr><td>Cuotas deudas</td><td>${fmt(m.debtDue)}</td></tr><tr><td>Resultado</td><td><b>${fmt(m.result)}</b></td></tr></table>`}else if(type==='results'){body=`<table><tr><th>Mes</th><th>Trabajo</th><th>DEBITAR</th><th>Uber</th><th>Otros</th><th>Ingresos</th><th>Obligaciones</th><th>Resultado</th></tr>${months.map(x=>{let z=metrics(x);return `<tr><td>${x}</td><td>${fmt(z.work)}</td><td>${fmt(z.debitar)}</td><td>${fmt(z.uber)}</td><td>${fmt(z.other)}</td><td>${fmt(z.income)}</td><td>${fmt(z.due)}</td><td><b>${fmt(z.result)}</b></td></tr>`}).join('')}</table>`}else{let rows=[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]];body=`<table><tr><th>Fuente</th><th>Ingreso</th><th>Horas</th><th>$/hora</th><th>Peso ingreso</th></tr>${rows.map(x=>`<tr><td>${x[0]}</td><td>${fmt(x[1])}</td><td>${num(x[2])} h</td><td>${x[2]?fmt(x[1]/x[2]):'—'}</td><td>${pct(x[1],m.income)}%</td></tr>`).join('')}</table>`}let w=window.open('','_blank');w.document.write(`<!doctype html><html><head><title>${title} · ${state.selectedMonth}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#142033}header{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #42cfdf;padding-bottom:12px;margin-bottom:24px}header img{width:190px;max-height:65px;object-fit:contain}h1{font-size:22px;margin:0}p{color:#66788b}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.summary div{border:1px solid #dce6ef;border-radius:10px;padding:14px}.summary small{display:block;color:#66788b}.summary b{font-size:20px;display:block;margin-top:5px}table{width:100%;border-collapse:collapse;font-size:11px}th{background:#0b1728;color:white;text-align:left}th,td{padding:8px;border:1px solid #dce6ef}td:not(:first-child){text-align:right}footer{position:fixed;bottom:0;font-size:9px;color:#8795a3}.note{font-size:10px;color:#66788b;margin-top:16px}</style></head><body><header><img src="${reportLogo()}"><div><h1>${title}</h1><p>Período ${state.selectedMonth} · emitido ${new Date().toLocaleDateString('es-CL')}</p></div></header>${body}<p class="note">Centro de Operaciones DEBITAR · reporte generado desde los registros del sistema.</p><footer>DEBITAR · Impuestos · Contabilidad · Remuneraciones</footer><script>setTimeout(()=>window.print(),500)<\/script></body></html>`);w.document.close()}
const oldDashboard=dashboard;dashboard=function(){let m=metrics(),time=m.workHours+m.debHours+m.uberHours,objs=state.objectives||[],pendingTasks=(state.tasks||[]).filter(t=>t.status!=='Hecha').slice(0,4),walletTotal=state.wallets.reduce((a,w)=>a+(+w.balance||0),0);return `<div class="hero"><div><span class="eyebrow">CENTRO DE OPERACIONES</span><h2>Control del mes · ${state.selectedMonth}</h2><p>Dinero, tiempo, clientes y objetivos en una sola lectura.</p></div><div class="hero-number"><small>Saldo en billeteras</small><b>${fmt(walletTotal)}</b><span class="${m.result>=0?'positive':'negative'}">Resultado ${fmt(m.result)}</span></div></div><div class="grid dash5">${kpi('Ingresos',fmt(m.income),`DEBITAR ${pct(m.debitar,m.income)}% · Uber ${pct(m.uber,m.income)}%`)}${kpi('Pagado',fmt(m.paid),`Pendiente ${fmt(m.pending)}`)}${kpi('Meta Uber',fmt(m.uberMissing),`Logrado ${fmt(m.uber)}`)}${kpi('Horas productivas',num(time)+' h',`DEBITAR ${num(m.debHours)} · Uber ${num(m.uberHours)}`)}${kpi('Cartera DEBITAR',fmt(m.expectedDebitar),`${state.clients.filter(c=>c.active).length} clientes`)}</div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Ingresos por fuente</h2><span class="pill">${fmt(m.income)}</span></div>${bars([['Trabajo',m.work],['DEBITAR',m.debitar],['Uber',m.uber],['Otros',m.other]],m.income,true)}</div><div class="card"><div class="section"><h2>Tiempo y valor por hora</h2><span class="pill">${num(time)} h</span></div>${[['Trabajo',m.work,m.workHours],['DEBITAR',m.debitar,m.debHours],['Uber',m.uber,m.uberHours]].map(x=>`<div class="productivity"><div><b>${x[0]}</b><small>${num(x[2])} h · ${pct(x[2],time)}% del tiempo</small></div><strong>${x[2]?fmt(x[1]/x[2])+'/h':'—'}</strong></div>`).join('')}</div></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section"><h2>Objetivos</h2><button class="linkbtn" data-go="Objetivos">Ver</button></div>${objs.map(o=>`<div class="goalmini"><div class="split"><b>${esc(o.name)}</b><span>${pct(o.current,o.target)}%</span></div><div class="bar"><i style="width:${Math.min(100,pct(o.current,o.target))}%"></i></div><small>${fmt(o.current)} de ${fmt(o.target)}</small></div>`).join('')}</div><div class="card"><div class="section"><h2>Próximas tareas</h2><button class="linkbtn" data-go="Tareas">Ver agenda</button></div>${pendingTasks.length?pendingTasks.map(t=>`<div class="line"><b>${esc(t.title)}</b><small class="muted block">${esc(t.client||'')} · ${t.due||'sin fecha'} ${t.time||''}</small></div>`).join(''):'<div class="empty">Sin tareas pendientes.</div>'}</div></div>`}

// ===== v0.6 incremental upgrade: preserves v0.5 data model and migrates version 3 =====
const V06_CATEGORIES=['Vivienda','Alimentación','Servicios básicos','Telecomunicaciones','Familia','Movilización','Auto','Deudas','Salud','Educación','DEBITAR/Negocio','Ocio','Gasto hormiga','Otros'];
function normCategory(c){let x=String(c||'Otros').trim().toLowerCase();let map={'hogar':'Alimentación','alimentacion':'Alimentación','alimentación':'Alimentación','gasto hormiga':'Gasto hormiga','deudas':'Deudas','servicios básicos':'Servicios básicos','servicios basicos':'Servicios básicos','movilización':'Movilización','movilizacion':'Movilización','telecomunicaciones':'Telecomunicaciones','familia':'Familia','vivienda':'Vivienda','auto':'Auto','otros':'Otros'};return map[x]||c||'Otros'}
function suggestedNature(c){c=normCategory(c);return ['Gasto hormiga','Ocio'].includes(c)?'Ajustable':['Deudas','Familia'].includes(c)?'Comprometido':['Vivienda','Alimentación','Servicios básicos','Salud','Educación'].includes(c)?'Esencial':'Ajustable'}
function migrate06(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('El archivo no contiene un respaldo DEBITAR válido');let x=Object.assign(clone(seed),raw);['wallets','clients','expenseTemplates','debts','incomes','transfers','collections','uberTurns','debitarSessions','objectives','otherSources','uberTrips','objectiveContributions','tasks','prospects'].forEach(k=>x[k]=Array.isArray(raw[k])?raw[k]:(x[k]||[]));x.expenseMonths=raw.expenseMonths&&typeof raw.expenseMonths==='object'?raw.expenseMonths:{};x.workSettings=Object.assign({},seed.workSettings,raw.workSettings||{});x.uberSettings=Object.assign({},seed.uberSettings,raw.uberSettings||{});x.uberActiveShift=raw.uberActiveShift||null;x.projects=Array.isArray(raw.projects)?raw.projects:[];x.extraServices=Array.isArray(raw.extraServices)?raw.extraServices:[];x.expenseTemplates=x.expenseTemplates.map(e=>({...e,category:normCategory(e.category),expenseType:e.expenseType||'Recurrente mensual',nature:e.nature||suggestedNature(e.category)}));for(const m of Object.keys(x.expenseMonths)){for(const id of Object.keys(x.expenseMonths[m]||{})){let o=x.expenseMonths[m][id];o.category=normCategory(o.category||x.expenseTemplates.find(e=>e.id===id)?.category);o.nature=o.nature||suggestedNature(o.category);o.expenseType=o.expenseType||x.expenseTemplates.find(e=>e.id===id)?.expenseType||'Recurrente mensual'}}x.version=4;return x}
state=migrate06(state);save();
function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let raw=JSON.parse(r.result.replace(/^\uFEFF/,''));let next=migrate06(raw);if(!next.wallets.length&&!next.clients.length&&!next.incomes.length)throw Error('El respaldo está vacío');state=next;state.uiPrefs=Object.assign({theme:'dark',budget:'55/25/20',group:'Mi jornada'},state.uiPrefs||{});state.walletAdjustments=Array.isArray(state.walletAdjustments)?state.walletAdjustments:[];localStorage.setItem(KEY,JSON.stringify(state));toast(`Respaldo cargado: ${state.wallets.length} billeteras · ${state.clients.length} clientes · ${state.incomes.length} ingresos`);shell()}catch(err){alert('No se pudo importar: '+err.message)}};r.readAsText(f)}
function monthExpenses(m=state.selectedMonth){let out=state.expenseTemplates.filter(e=>e.active!==false).map(e=>{let ov=(state.expenseMonths[m]||{})[e.id]||{};return {...e,...ov,base:e.amount,status:ov.status||'Pendiente',paidAmount:+ov.paidAmount||0,wallet:ov.wallet||'',paidDate:ov.paidDate||'',expenseType:e.expenseType||'Recurrente mensual',nature:ov.nature||e.nature||suggestedNature(e.category),category:normCategory(ov.category||e.category)}});let seen=new Set(out.map(e=>e.id));for(const [id,ov] of Object.entries(state.expenseMonths[m]||{}))if(!seen.has(id)&&ov&&ov.name)out.push({...ov,id,status:ov.status||'Pendiente',amount:+ov.amount||0,paidAmount:+ov.paidAmount||0,expenseType:ov.expenseType||'Solo este mes',nature:ov.nature||suggestedNature(ov.category),category:normCategory(ov.category)});return out.filter(e=>e.status!=='Eliminado')}
function expenses(){let ex=monthExpenses().sort((a,b)=>(+a.day||99)-(+b.day||99)),pending=ex.filter(e=>e.status!=='Pagado'),done=ex.filter(e=>e.status==='Pagado'),total=ex.filter(e=>e.status!=='Postergado').reduce((a,e)=>a+(+e.amount||0),0),paid=done.reduce((a,e)=>a+(+e.paidAmount||+e.amount||0),0),adj=ex.filter(e=>e.status!=='Postergado'&&e.nature==='Ajustable').reduce((a,e)=>a+(+e.amount||0),0);const table=rows=>`<div class="card tablewrap"><table><thead><tr><th>Concepto</th><th>Categoría</th><th>Naturaleza</th><th>Tipo</th><th>Monto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr class="${e.status==='Pagado'?'row-paid':e.status==='Postergado'?'row-postponed':''}"><td><b>${esc(e.name)}</b><small class="block muted">día ${e.day||'—'}</small></td><td>${esc(e.category)}</td><td><span class="pill">${esc(e.nature)}</span></td><td>${esc(e.expenseType)}</td><td class="num">${fmt(e.amount)}</td><td><span class="pill ${e.status==='Pagado'?'ok':e.status==='Pendiente'?'wait':''}">${e.status}</span></td><td class="actions">${e.status==='Pagado'?`<button class="btn ghost sm" data-unpay-exp="${e.id}">↩ Revertir</button>`:`<button class="btn sm" data-pay-exp="${e.id}">Pagar</button><button class="btn ghost sm" data-post-exp="${e.id}">Postergar</button>`}<button class="btn ghost sm" data-edit-exp="${e.id}">Editar</button><button class="btn ghost sm" data-del-exp="${e.id}">Quitar mes</button></td></tr>`).join(''):'<tr><td colspan="7" class="muted">No hay gastos en esta sección.</td></tr>'}</tbody></table></div>`;return `<div class="grid kpis">${kpi('Total gastos',fmt(total),'Mes actual')}${kpi('Pagado',fmt(paid))}${kpi('Pendiente',fmt(Math.max(0,total-paid)))}${kpi('Gastos ajustables',fmt(adj),'Potencial a revisar')}</div><div class="section"><h2>Por pagar · ${pending.length} gastos</h2><button class="btn" data-act="newexpense">+ Agregar gasto</button></div>${table(pending)}<details class="card" style="margin-top:16px;padding:16px"><summary style="cursor:pointer;font-weight:700">✓ Pagados (${done.length}) · ${fmt(paid)} — Ver historial</summary><div style="margin-top:14px">${table(done)}</div></details>`}

function expenseModal(){let opts=V06_CATEGORIES.map(c=>`<option>${c}</option>`).join('');modal(`<div class="form-grid"><div class="field"><label>Concepto</label><input id="n"></div><div class="field"><label>Categoría</label><select id="c">${opts}</select></div><div class="field"><label>Monto</label><input id="a" type="number"></div><div class="field"><label>Día</label><input id="d" type="number" min="1" max="31" value="1"></div><div class="field"><label>Tipo de gasto</label><select id="ty"><option>Solo este mes</option><option>Recurrente mensual</option></select></div><div class="field"><label>Naturaleza</label><select id="na"><option>Esencial</option><option>Comprometido</option><option selected>Ajustable</option></select></div></div><button class="btn" id="s">Guardar gasto</button>`,b=>{$('#c',b).onchange=()=>$('#na',b).value=suggestedNature($('#c',b).value);$('#s',b).onclick=()=>{let id=uid('e'),obj={id,name:$('#n',b).value.trim(),category:$('#c',b).value,amount:+$('#a',b).value||0,day:+$('#d',b).value||1,expenseType:$('#ty',b).value,nature:$('#na',b).value,active:true};if(!obj.name||obj.amount<=0)return alert('Completa concepto y monto');if(obj.expenseType==='Recurrente mensual')state.expenseTemplates.push(obj);else{state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...obj,status:'Pendiente'}}save('Gasto guardado');b.remove();render()}})}
function editExpense(id){let e=monthExpenses().find(x=>x.id===id);if(!e)return;let opts=V06_CATEGORIES.map(c=>`<option ${c===e.category?'selected':''}>${c}</option>`).join('');modal(`<div class="form-grid"><div class="field"><label>Concepto</label><input id="n" value="${esc(e.name)}"></div><div class="field"><label>Categoría</label><select id="c">${opts}</select></div><div class="field"><label>Monto este mes</label><input id="a" type="number" value="${e.amount}"></div><div class="field"><label>Naturaleza</label><select id="na"><option ${e.nature==='Esencial'?'selected':''}>Esencial</option><option ${e.nature==='Comprometido'?'selected':''}>Comprometido</option><option ${e.nature==='Ajustable'?'selected':''}>Ajustable</option></select></div></div><button class="btn" id="s">Guardar cambios del mes</button>`,b=>$('#s',b).onclick=()=>{state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...(state.expenseMonths[state.selectedMonth][id]||{}),name:$('#n',b).value,amount:+$('#a',b).value||0,category:$('#c',b).value,nature:$('#na',b).value,expenseType:e.expenseType,status:e.status};save('Gasto actualizado');b.remove();render()})}
function postponeExpense(id){let e=monthExpenses().find(x=>x.id===id);if(!e)return;state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...(state.expenseMonths[state.selectedMonth][id]||{}),name:e.name,amount:e.amount,category:e.category,nature:e.nature,expenseType:e.expenseType,status:'Postergado'};save('Gasto postergado');render()}
function removeExpenseMonth(id){let e=monthExpenses().find(x=>x.id===id);if(!e||!confirm('¿Quitar este gasto del mes actual?'))return;state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...(state.expenseMonths[state.selectedMonth][id]||{}),name:e.name,status:'Eliminado'};save('Gasto quitado del mes');render()}
function debtBalance(d){return +(d.balance??d.total??d.amount)||0}
function debts(){let all=state.debts||[],month=state.selectedMonth,scheduled=all.filter(d=>ym(d.date)===month),total=all.reduce((a,d)=>a+debtBalance(d),0),next=new Date(month+'-01T12:00:00');next.setMonth(next.getMonth()+1);let nm=next.toISOString().slice(0,7),nextAmt=all.filter(d=>ym(d.date)===nm).reduce((a,d)=>a+(+d.amount||0),0);return `<div class="grid kpis">${kpi('Saldo deuda',fmt(total),'Total registrado')}${kpi('Cuotas del mes',fmt(scheduled.reduce((a,d)=>a+(+d.amount||0),0)))}${kpi('Pendiente mes',fmt(scheduled.filter(d=>d.status!=='Pagada').reduce((a,d)=>a+(+d.amount||0),0)))}${kpi('Próximo mes',fmt(nextAmt),nm)}</div><div class="section"><h2>Deudas</h2><button class="btn" data-act="newdebt">+ Registrar deuda</button></div><div class="card tablewrap"><table><thead><tr><th>Acreedor</th><th>Saldo / monto</th><th>Próxima fecha</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${all.map(d=>`<tr><td><b>${esc(d.name)}</b></td><td class="num">${fmt(debtBalance(d))}</td><td>${d.date||'—'}</td><td>${esc(d.status||'Pendiente')}</td><td><button class="btn sm" data-debt-exp="${d.id}">Agregar cuota a gastos</button></td></tr>`).join('')}</tbody></table></div>`}
function debtModal(){modal(`<div class="form-grid"><div class="field"><label>Acreedor</label><input id="n"></div><div class="field"><label>Deuda total / saldo inicial</label><input id="t" type="number"></div><div class="field"><label>Próxima fecha</label><input id="d" type="date"></div><div class="field"><label>Cuota referencial</label><input id="a" type="number"></div></div><button class="btn" id="s">Guardar deuda</button>`,b=>$('#s',b).onclick=()=>{let total=+$('#t',b).value||0;state.debts.push({id:uid('d'),name:$('#n',b).value,date:$('#d',b).value,amount:+$('#a',b).value||0,total,balance:total,status:'Pendiente'});save('Deuda registrada');b.remove();render()})}
