const dashboardV05=dashboard;dashboard=function(){let ex=monthExpenses(),m=metrics(),time=m.workHours+m.debHours+m.uberHours,walletTotal=state.wallets.filter(w=>w.active).reduce((a,w)=>a+(+w.balance||0),0),activeEx=ex.filter(e=>e.status!=='Postergado'&&e.status!=='Eliminado'),total=activeEx.reduce((a,e)=>a+(+e.amount||0),0),paid=activeEx.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0),adj=activeEx.filter(e=>e.nature==='Ajustable').reduce((a,e)=>a+(+e.amount||0),0),cats={};activeEx.forEach(e=>cats[e.category||'Otros']=(cats[e.category||'Otros']||0)+(+e.amount||0));let rows=Object.entries(cats).sort((a,b)=>b[1]-a[1]),sum=rows.reduce((a,x)=>a+x[1],0)||1,pal=['#24bfd0','#5636a8','#7088c8','#36a879','#d29b3c','#c85c78','#60768d','#8b67b3'],acc=0,parts=rows.map((x,i)=>{let a=acc/sum*360;acc+=x[1];return `${pal[i%pal.length]} ${a}deg ${acc/sum*360}deg`}).join(','),list=rows.slice(0,8).map((x,i)=>`<div class="catline"><i style="background:${pal[i%pal.length]}"></i><span>${esc(x[0])}</span><b>${fmt(x[1])}</b><small>${pct(x[1],sum)}%</small></div>`).join('');return `<section class="dash-head"><div><span class="eyebrow">CONTROL MENSUAL</span><h2>${state.selectedMonth}</h2><p>Obligaciones, caja, actividad y capacidad de ajuste en una sola vista.</p></div><div class="dash-result ${m.result>=0?'good':'bad'}"><small>Resultado proyectado</small><b>${fmt(m.result)}</b><span>${m.result>=0?'Superávit':'Déficit'}</span></div></section><div class="grid dash8">${kpi('Total a pagar',fmt(total),'Obligaciones activas del mes')}${kpi('Pagado actual',fmt(paid),`${pct(paid,total)}% cubierto`)}${kpi('Pendiente',fmt(Math.max(0,total-paid)),'Por resolver')}${kpi('Total ingresos',fmt(m.income),'Ingresos registrados')}${kpi('Horas trabajadas',num(time)+' h','Trabajo + DEBITAR + Uber')}${kpi('Meta Uber',fmt(m.uberTarget),`Faltan ${fmt(m.uberMissing)}`)}${kpi('Cartera DEBITAR',fmt(m.expectedDebitar),`Cobrado ${fmt(m.debitar)}`)}${kpi('Billeteras',fmt(walletTotal),'Saldo cuentas activas')}</div><div class="grid dash-lower"><div class="card spend-card"><div class="section"><div><h2>¿Dónde se va mi dinero?</h2><small class="muted">Distribución de gastos por categoría</small></div><span class="pill">${fmt(total)}</span></div><div class="spend-wrap"><div class="donut" style="background:conic-gradient(${parts||'#dce4ed 0deg 360deg'})"><div><b>${fmt(total)}</b><small>Total mes</small></div></div><div class="catlist">${list||'<div class="empty">Sin gastos registrados.</div>'}</div></div></div><div class="card decision-card"><div class="section"><h2>Decisión rápida</h2><span class="pill">${pct(paid,total)}%</span></div><div class="progress-big"><i style="width:${Math.min(100,pct(paid,total))}%"></i></div><div class="decision-row"><span>Pagado</span><b class="positive">${fmt(paid)}</b></div><div class="decision-row"><span>Pendiente</span><b>${fmt(Math.max(0,total-paid))}</b></div><div class="decision-row"><span>Gastos ajustables</span><b>${fmt(adj)}</b></div><div class="decision-row"><span>Meta Uber faltante</span><b>${fmt(m.uberMissing)}</b></div><button class="btn ghost wide" data-go="Gastos">Revisar gastos</button></div></div><div class="grid two dash-bottom"><div class="card"><div class="section"><h2>Origen de ingresos</h2><span class="pill">${fmt(m.income)}</span></div>${bars([['Trabajo',m.work],['DEBITAR',m.debitar],['Uber',m.uber],['Otros',m.other]],m.income,true)}</div><div class="card"><div class="section"><h2>Uso del tiempo</h2><span class="pill">${num(time)} h</span></div>${bars([['Trabajo',m.workHours],['DEBITAR',m.debHours],['Uber',m.uberHours]],time,false,' h')}</div></div>`}

