function ensureV07(){
  state.projects=Array.isArray(state.projects)?state.projects:[];
  state.receivables=Array.isArray(state.receivables)?state.receivables:[];
  state.tasks=Array.isArray(state.tasks)?state.tasks:[];
  state.version=5;
}
function todayISO(){let d=new Date(),z=d.getTimezoneOffset()*60000;return new Date(d-z).toISOString().slice(0,10)}
function addTaskDays(start,days,business){if(!start||!days)return start||'';let d=new Date(start+'T12:00:00'),n=0;while(n<days){d.setDate(d.getDate()+1);if(!business||![0,6].includes(d.getDay()))n++}return d.toISOString().slice(0,10)}
function taskDue(t){return t.due||addTaskDays(t.startDate,+t.days||0,t.dayType==='Días hábiles')}
function taskAttention(){let now=todayISO(),p=(state.tasks||[]).filter(t=>t.status!=='Hecha'),over=p.filter(t=>taskDue(t)&&taskDue(t)<now),today=p.filter(t=>taskDue(t)===now);return{pending:p.length,overdue:over.length,today:today.length,attention:over.length+today.length}}
function projectInvestment(p){let detail=[...(p.implements||[]),...(p.procedures||[])].reduce((a,x)=>a+(+x.amount||0),0);return (+p.investment||0)||detail}
function parseMoneyLines(v){return String(v||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{let a=line.split('|');return{name:(a[0]||'').trim(),amount:+String(a[1]||0).replace(/[^0-9.-]/g,'')||0,note:(a.slice(2).join('|')||'').trim()}})}
function moneyLines(a){return (a||[]).map(x=>`${x.name||''} | ${x.amount||0}${x.note?' | '+x.note:''}`).join('\n')}

const metricsV07Base=metrics;
metrics=function(m=state.selectedMonth){ensureV07();let x=metricsV07Base(m);let expected=state.clients.filter(c=>c.active).reduce((a,c)=>a+(+c.fee||0),0);let target=Math.max(0,x.due-x.work-x.other-expected);x.expectedDebitar=expected;x.uberTarget=target;x.uberMissing=Math.max(0,target-x.uber);return x}

shell=function(){ensureV07();let a=taskAttention();let left=[['Inicio','⌂'],['Finanzas','◫'],['Gastos','↓'],['Deudas','◈']];let right=[['DEBITAR','D'],['Uber','U'],['Proyectos','P'],['Tareas','✓'],['Objetivos','◎'],['Reportes','▤'],['Configuración','⚙']];let buttons=(arr,side)=>arr.map(x=>{let badge=x[0]==='Tareas'&&a.attention?`<span class="task-badge">${a.attention}</span>`:'';return `<button class="dockbtn ${page===x[0]?'on':''}" data-p="${x[0]}"><span class="dockicon">${x[1]}</span><span class="docklabel">${x[0]}</span>${badge}</button>`}).join('');document.querySelector('#app').innerHTML=`<div class="shell shell-v061"><aside class="side side-left"><img class="logo" src="https://danielmunoz-debitar.github.io/centro-operaciones/assets/logo-debitar.png"><div class="nav docknav">${buttons(left,'left')}</div></aside><main class="main"><div class="top"><div class="title"><h1>${page}</h1><p>Centro de Operaciones · v0.7 · control y gestión DEBITAR</p></div><input class="month" id="month" type="month" value="${state.selectedMonth}"></div><div id="view"></div></main><aside class="side side-right compact-right"><div class="nav docknav">${buttons(right,'right')}</div></aside></div>`;$$('[data-p]').forEach(b=>b.onclick=()=>{page=b.dataset.p;shell()});$('#month').onchange=e=>{state.selectedMonth=e.target.value;save();render()};render();if(a.attention&&!sessionStorage.getItem('v07-task-alert')){sessionStorage.setItem('v07-task-alert','1');setTimeout(()=>toast(`Tareas requieren atención: ${a.overdue} vencidas · ${a.today} vencen hoy`),300)}}

