finances=function(){ensureV07();let ins=incomesM(),ws=state.wallets,rs=state.receivables||[],open=rs.filter(r=>(+r.balance||0)>0),over=open.filter(r=>r.due&&r.due<todayISO());return `<div class="actions"><button class="btn" data-act="income">+ Registrar ingreso</button><button class="btn ghost" data-act="transfer">↔ Transferir</button><button class="btn ghost" data-act="newrecv">+ Cuenta por cobrar</button></div><div class="grid three" style="margin-top:14px">${ws.map(w=>`<div class="card wallet"><span class="pill">${esc(w.type)}</span><h3>${esc(w.name)}</h3><div class="big">${fmt(w.balance)}</div><small class="muted">${w.active?'Activa':'Inactiva'}</small></div>`).join('')}</div><div class="grid three" style="margin-top:14px">${kpi('Por cobrar',fmt(open.reduce((a,r)=>a+(+r.balance||0),0)),`${open.length} cuentas abiertas`)}${kpi('Vencido por cobrar',fmt(over.reduce((a,r)=>a+(+r.balance||0),0)),`${over.length} vencidas`)}${kpi('Cobrado este mes',fmt(rs.reduce((a,r)=>a+(r.payments||[]).filter(p=>p.date?.startsWith(state.selectedMonth)).reduce((b,p)=>b+(+p.amount||0),0),0)),'Pasa a Otros ingresos')}</div><div class="section"><h2>Cuentas por cobrar</h2></div><div class="card tablewrap">${rs.length?`<table><thead><tr><th>Persona / entidad</th><th>Concepto</th><th>Original</th><th>Saldo</th><th>Vence</th><th>Estado</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.concept||'')}</td><td>${fmt(r.amount)}</td><td><b>${fmt(r.balance)}</b></td><td>${r.due||'—'}</td><td>${(+r.balance||0)<=0?'<span class="pill ok">Cobrado</span>':r.due&&r.due<todayISO()?'<span class="pill bad">Vencido</span>':'<span class="pill wait">Pendiente</span>'}</td><td>${(+r.balance||0)>0?`<button class="btn sm" data-collectrecv="${r.id}">Registrar cobro</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Aquí registra dinero que terceros te deben y que todavía no has recibido.</div>'}</div><div class="section"><h2>Ingresos registrados · ${state.selectedMonth}</h2></div><div class="card tablewrap">${ins.length?`<table><thead><tr><th>Fecha</th><th>Fuente</th><th>Monto</th><th>Billetera</th><th>Nota</th></tr></thead><tbody>${ins.map(i=>`<tr><td>${i.date}</td><td>${esc(i.source)}</td><td>${fmt(i.amount)}</td><td>${esc(walletName(i.wallet))}</td><td>${esc(i.note||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Sin ingresos registrados.</div>'}</div>`}

function receivableModal(){modal(`<div class="form-grid"><div class="field"><label>Persona / entidad</label><input id="rn"></div><div class="field"><label>Concepto</label><input id="rc"></div><div class="field"><label>Monto que te deben</label><input id="ra" type="number"></div><div class="field"><label>Fecha comprometida</label><input id="rd" type="date"></div></div><button class="btn" id="rs">Guardar cuenta por cobrar</button>`,b=>$('#rs',b).onclick=()=>{let a=+$('#ra',b).value||0,n=$('#rn',b).value.trim();if(!n||a<=0)return alert('Completa persona y monto');state.receivables.push({id:uid('recv'),name:n,concept:$('#rc',b).value,amount:a,balance:a,due:$('#rd',b).value,payments:[]});save('Cuenta por cobrar guardada');b.remove();render()})}
function collectReceivable(id){let r=state.receivables.find(x=>x.id===id);if(!r)return;modal(`<div class="form-grid"><div class="field"><label>Monto recibido</label><input id="ca" type="number" value="${r.balance}"></div><div class="field"><label>Fecha</label><input id="cd" type="date" value="${todayISO()}"></div><div class="field"><label>Billetera</label><select id="cw">${walletOptions()}</select></div></div><button class="btn" id="cs">Registrar cobro</button>`,b=>$('#cs',b).onclick=()=>{let a=Math.min(+$('#ca',b).value||0,+r.balance||0),w=$('#cw',b).value,d=$('#cd',b).value;if(a<=0)return;r.balance-=a;r.payments??=[];r.payments.push({id:uid('rp'),date:d,amount:a,wallet:w});state.incomes.push({id:uid('i'),date:d,source:'Otro ingreso',amount:a,wallet:w,note:`Cobro: ${r.name} · ${r.concept||''}`});let ww=state.wallets.find(x=>x.id===w);if(ww)ww.balance+=a;save('Cobro registrado');b.remove();render()})}

tasksPage=function(){let ts=(state.tasks||[]).slice().sort((a,b)=>(taskDue(a)||'9999').localeCompare(taskDue(b)||'9999')),now=todayISO(),pending=ts.filter(t=>t.status!=='Hecha'),done=ts.filter(t=>t.status==='Hecha'),over=pending.filter(t=>taskDue(t)&&taskDue(t)<now),soon=pending.filter(t=>taskDue(t)&&taskDue(t)>=now&&taskDue(t)<=addTaskDays(now,1,false));return `<div class="grid four">${kpi('Pendientes',pending.length)}${kpi('Vencidas',over.length,over.length?'Requieren atención':'Al día')}${kpi('Próximas 24 h',soon.length)}${kpi('Completadas',done.length)}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="newtask">+ Nueva tarea</button></div><div class="section"><h2>Agenda de trabajo</h2></div><div class="card tablewrap">${ts.length?`<table><thead><tr><th>Estado</th><th>Tarea</th><th>Inicio / plazo</th><th>Fecha límite</th><th>Prioridad</th><th>Horas</th><th></th></tr></thead><tbody>${ts.map(t=>{let du=taskDue(t),late=t.status!=='Hecha'&&du&&du<now;return `<tr class="${late?'task-overdue':''}"><td><button class="btn ${t.status==='Hecha'?'ghost':''} sm" data-task-toggle="${t.id}">${t.status==='Hecha'?'✓ Hecha':'Pendiente'}</button></td><td><b>${esc(t.title)}</b><small class="muted block">${esc(t.client||'General')} · ${esc(t.note||'')}</small></td><td>${t.startDate||'—'}<small class="block muted">${t.days?`${t.days} ${esc(t.dayType||'Días corridos')}`:''}</small></td><td><b>${du||'—'}</b>${late?'<small class="block badtext">Vencida</small>':''}</td><td><span class="pill ${t.priority==='Alta'?'bad':t.priority==='Media'?'wait':''}">${esc(t.priority||'Media')}</span></td><td>${num(t.hours||0)} h</td><td><button class="btn ghost sm" data-task-edit="${t.id}">Editar</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Crea tareas y asigna cuántos días tienes para completarlas.</div>'}</div>`}

taskModal=function(id){let t=id?(state.tasks||[]).find(x=>x.id===id):null,clients=state.clients.filter(c=>c.active);modal(`<div class="form-grid"><div class="field"><label>Tarea</label><input id="tt" value="${esc(t?.title||'')}"></div><div class="field"><label>Cliente / área</label><select id="cl"><option>General DEBITAR</option>${clients.map(c=>`<option ${t?.client===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}<option ${t?.client==='Personal'?'selected':''}>Personal</option></select></div><div class="field"><label>Fecha de inicio</label><input id="st" type="date" value="${t?.startDate||t?.due||todayISO()}"></div><div class="field"><label>Días asignados</label><input id="dy" type="number" min="0" value="${t?.days||1}"></div><div class="field"><label>Tipo de plazo</label><select id="dt"><option ${t?.dayType!=='Días hábiles'?'selected':''}>Días corridos</option><option ${t?.dayType==='Días hábiles'?'selected':''}>Días hábiles</option></select></div><div class="field"><label>Prioridad</label><select id="pr"><option ${t?.priority==='Alta'?'selected':''}>Alta</option><option ${!t||t?.priority==='Media'?'selected':''}>Media</option><option ${t?.priority==='Baja'?'selected':''}>Baja</option></select></div><div class="field"><label>Horas estimadas</label><input id="hr" type="number" step="0.5" value="${t?.hours||0}"></div><div class="field"><label>Nota</label><input id="no" value="${esc(t?.note||'')}"></div></div><button class="btn" id="sv">Guardar tarea</button>`,b=>$('#sv',b).onclick=()=>{let obj=t||{id:uid('task'),status:'Pendiente'};obj.title=$('#tt',b).value.trim();obj.client=$('#cl',b).value;obj.startDate=$('#st',b).value;obj.days=+$('#dy',b).value||0;obj.dayType=$('#dt',b).value;obj.due=addTaskDays(obj.startDate,obj.days,obj.dayType==='Días hábiles');obj.priority=$('#pr',b).value;obj.hours=+$('#hr',b).value||0;obj.note=$('#no',b).value;if(!obj.title)return alert('Escribe una tarea');if(!t)state.tasks.push(obj);save('Tarea guardada');b.remove();shell()})}

expenseModal=function(){let opts=V06_CATEGORIES.map(c=>`<option>${c}</option>`).join('');modal(`<div class="form-grid"><div class="field"><label>Concepto</label><input id="n"></div><div class="field"><label>Categoría</label><select id="c">${opts}</select></div><div class="field"><label>Monto</label><input id="a" type="number"></div><div class="field"><label>Día</label><input id="d" type="number" min="1" max="31" value="1"></div><div class="field"><label>Tipo de gasto</label><select id="ty"><option>Solo este mes</option><option>Recurrente mensual</option></select></div><div class="field"><label>Naturaleza</label><select id="na"><option>Esencial</option><option>Comprometido</option><option selected>Ajustable</option></select></div></div><label class="instant-pay"><input id="ip" type="checkbox"> <b>Este gasto ya está pagado</b><small>Útil para gastos hormiga y compras que registras después de pagar.</small></label><div id="paybox" class="form-grid paybox hidden"><div class="field"><label>Billetera usada</label><select id="w">${walletOptions()}</select></div><div class="field"><label>Fecha de pago</label><input id="pd" type="date" value="${todayISO()}"></div></div><button class="btn" id="s">Guardar gasto</button>`,b=>{$('#c',b).onchange=()=>$('#na',b).value=suggestedNature($('#c',b).value);$('#ip',b).onchange=()=>$('#paybox',b).classList.toggle('hidden',!$('#ip',b).checked);$('#s',b).onclick=()=>{let id=uid('e'),paid=$('#ip',b).checked,obj={id,name:$('#n',b).value.trim(),category:$('#c',b).value,amount:+$('#a',b).value||0,day:+$('#d',b).value||1,expenseType:$('#ty',b).value,nature:$('#na',b).value,active:true};if(!obj.name||obj.amount<=0)return alert('Completa concepto y monto');if(obj.expenseType==='Recurrente mensual')state.expenseTemplates.push(obj);state.expenseMonths[state.selectedMonth]??={};state.expenseMonths[state.selectedMonth][id]={...obj,status:paid?'Pagado':'Pendiente',...(paid?{paidAmount:obj.amount,wallet:$('#w',b).value,paidDate:$('#pd',b).value}:{})};if(paid){let ww=state.wallets.find(x=>x.id===$('#w',b).value);if(ww)ww.balance-=obj.amount}save(paid?'Gasto guardado como pagado':'Gasto guardado');b.remove();render()}})}

projectPage=function(){ensureV07();let ps=state.projects||[],active=ps.filter(p=>p.status==='En curso'),invest=active.reduce((a,p)=>a+projectInvestment(p),0),hours=active.reduce((a,p)=>a+(+p.hoursNeeded||0),0),mvp=active.reduce((a,p)=>a+(+p.mvpCost||0),0);return `<div class="grid four">${kpi('En curso',active.length,'Máximo recomendado: 2')}${kpi('Inversión estimada',fmt(invest),'Proyectos en curso')}${kpi('MVP acumulado',fmt(mvp),'Capital mínimo para validar')}${kpi('Horas requeridas',num(hours)+' h','Estimación total')}</div><div class="section"><div><h2>Evaluación e implementación</h2><small class="muted">Presupuesto, trámites, tiempo, MVP y recuperación.</small></div><button class="btn" data-act="newproject">+ Proyecto</button></div><div class="project-grid">${ps.length?ps.map(p=>{let inv=projectInvestment(p),base=+p.baseProfit||0,worst=+p.worstProfit||0;return `<button class="project-card" data-project="${p.id}"><div class="split"><span class="pill">${esc(p.status||'Incubadora')}</span><b>${p.progress||0}%</b></div><h3>${esc(p.name)}</h3><p>${esc(p.objective||'')}</p><div class="project-metrics"><span>Inversión<b>${fmt(inv)}</b></span><span>MVP<b>${fmt(p.mvpCost||0)}</b></span><span>Horas<b>${num(p.hoursNeeded||0)} h</b></span><span>Payback base<b>${base>0?num(inv/base)+' meses':'—'}</b></span><span>Escenario adverso<b>${worst>0?num(inv/worst)+' meses':'No recupera'}</b></span><span>Puesta en marcha<b>${p.launchDays?`${p.launchDays} días`:'—'}</b></span></div><small>Próximo hito: ${esc(p.next||'—')}</small></button>`}).join(''):'<div class="card empty">Aún no hay proyectos. Cada idea puede evaluarse antes de comprometer capital.</div>'}</div>`}

projectModal=function(id){ensureV07();let p=id?state.projects.find(x=>x.id===id):null;if(!p&&(state.projects||[]).filter(x=>x.status==='En curso').length>=2)toast('Ya tienes 2 proyectos en curso; evalúa Próximo o Incubadora');modal(`<div class="form-grid"><div class="field"><label>Proyecto</label><input id="pn" value="${esc(p?.name||'')}"></div><div class="field"><label>Tipo</label><select id="pt"><option ${p?.type==='Negocio / inversión'?'selected':''}>Negocio / inversión</option><option ${p?.type==='DEBITAR'?'selected':''}>DEBITAR</option><option ${p?.type==='Personal'?'selected':''}>Personal</option><option ${p?.type==='Mejora interna'?'selected':''}>Mejora interna</option></select></div><div class="field"><label>Objetivo</label><input id="po" value="${esc(p?.objective||'')}"></div><div class="field"><label>Estado</label><select id="ps"><option ${p?.status==='En curso'?'selected':''}>En curso</option><option ${p?.status==='Próximo'?'selected':''}>Próximo</option><option ${p?.status==='Incubadora'?'selected':''}>Incubadora</option><option ${p?.status==='Terminado'?'selected':''}>Terminado</option></select></div><div class="field"><label>Inicio</label><input id="pi" type="date" value="${p?.start||''}"></div><div class="field"><label>Días para poner en marcha</label><input id="pl" type="number" value="${p?.launchDays||0}"></div><div class="field"><label>Horas de trabajo requeridas</label><input id="ph" type="number" step="0.5" value="${p?.hoursNeeded||0}"></div><div class="field"><label>Avance %</label><input id="pp" type="number" min="0" max="100" value="${p?.progress||0}"></div><div class="field"><label>Inversión manual (si no detallas abajo)</label><input id="pinv" type="number" value="${p?.investment||0}"></div><div class="field"><label>MVP · inversión mínima para validar</label><input id="pmvp" type="number" value="${p?.mvpCost||0}"></div><div class="field"><label>Utilidad mensual escenario base</label><input id="pbase" type="number" value="${p?.baseProfit||0}"></div><div class="field"><label>Utilidad mensual escenario adverso</label><input id="pworst" type="number" value="${p?.worstProfit||0}"></div><div class="field"><label>Próximo hito</label><input id="pnext" value="${esc(p?.next||'')}"></div><div class="field"><label>Mínimo viable / criterio de validación</label><input id="pcrit" value="${esc(p?.mvpCriteria||'')}"></div></div><div class="project-edit-grid"><div class="field"><label>Implementos · una línea: nombre | monto | nota</label><textarea id="pimpl" rows="5">${esc(moneyLines(p?.implements))}</textarea></div><div class="field"><label>Cotizaciones · una línea: proveedor/opción | monto | detalle</label><textarea id="pquotes" rows="5">${esc(moneyLines(p?.quotes))}</textarea></div><div class="field"><label>Trámites · una línea: trámite | costo | plazo/organismo</label><textarea id="pproc" rows="5">${esc(moneyLines(p?.procedures))}</textarea></div><div class="field"><label>Riesgo / peor caso</label><textarea id="prisk" rows="5">${esc(p?.worstCase||'')}</textarea></div></div><button class="btn" id="psv">${p?'Guardar cambios':'Crear proyecto'}</button>`,b=>$('#psv',b).onclick=()=>{let obj=p||{id:uid('pj')};Object.assign(obj,{name:$('#pn',b).value.trim(),type:$('#pt',b).value,objective:$('#po',b).value,status:$('#ps',b).value,start:$('#pi',b).value,launchDays:+$('#pl',b).value||0,hoursNeeded:+$('#ph',b).value||0,progress:+$('#pp',b).value||0,investment:+$('#pinv',b).value||0,mvpCost:+$('#pmvp',b).value||0,baseProfit:+$('#pbase',b).value||0,worstProfit:+$('#pworst',b).value||0,next:$('#pnext',b).value,mvpCriteria:$('#pcrit',b).value,implements:parseMoneyLines($('#pimpl',b).value),quotes:parseMoneyLines($('#pquotes',b).value),procedures:parseMoneyLines($('#pproc',b).value),worstCase:$('#prisk',b).value});if(!obj.name)return alert('Escribe el nombre del proyecto');if(!p)state.projects.push(obj);save('Proyecto guardado');b.remove();render()})}

// La migración v0.7 conserva todo el respaldo previo y agrega únicamente colecciones nuevas.
const migrateV07Base=migrate06;
migrate06=function(raw){let x=migrateV07Base(raw);x.receivables=Array.isArray(raw.receivables)?raw.receivables:[];x.projects=Array.isArray(raw.projects)?raw.projects:[];x.version=5;return x}

ensureV07();save();shell();
/* ======================= fin v0.7 FINAL ======================= */

/* ========================= v0.8 DAILY OPERATING SYSTEM ========================= */
function ensureV08(){
  ensureV07();
  state.version=6;
  state.activityLog=Array.isArray(state.activityLog)?state.activityLog:[];
  state.usageDays=state.usageDays||{};
  state.operatingPlan=Object.assign({debitarWeeklyHours:10,uberWeeklyHours:9,sleepHours:7.5,debitarDays:[1,3,4,0],uberDays:[6,0],incomeTarget:3000000,independenceTarget:2000000,reserveTarget:3000000},state.operatingPlan||{});
}
function chileWallet(){return state.wallets.find(w=>(w.name||'').toLowerCase().includes('banco de chile'))}
function reserveMetrics(){let m=metrics(),w=chileWallet(),balance=+(w?.balance||0),pending=Math.max(0,+m.pending||0),free=Math.max(0,balance-pending);return{balance,pending,free,target:+state.operatingPlan.reserveTarget||3000000}}
function weekStart(d=new Date()){let x=new Date(d);let day=x.getDay();let diff=(day===0?-6:1-day);x.setDate(x.getDate()+diff);x.setHours(0,0,0,0);return x}
function inCurrentWeek(iso){if(!iso)return false;let d=new Date(iso),s=weekStart(),e=new Date(s);e.setDate(e.getDate()+7);return d>=s&&d<e}
function weeklyOps(){let dh=(state.debitarSessions||[]).filter(s=>inCurrentWeek(s.start)).reduce((a,s)=>a+(+s.hours||0),0),ut=(state.uberTurns||[]).filter(t=>inCurrentWeek(t.start)),uh=ut.reduce((a,t)=>a+(+t.hours||0),0),un=ut.reduce((a,t)=>a+(+t.net||0),0);return{debitarHours:dh,uberHours:uh,uberNet:un}}
function dailyOps(){let d=todayISO(),dh=(state.debitarSessions||[]).filter(s=>(s.start||'').slice(0,10)===d).reduce((a,s)=>a+(+s.hours||0),0),ut=(state.uberTurns||[]).filter(t=>(t.start||'').slice(0,10)===d),done=(state.tasks||[]).filter(t=>(t.completedAt||'').slice(0,10)===d).length;return{debitarHours:dh,uberTurns:ut.length,uberHours:ut.reduce((a,t)=>a+(+t.hours||0),0),tasksDone:done}}
function operatingAlerts(){ensureV08();let a=[],daily=dailyOps(),dow=new Date().getDay(),inc=(state.projects||[]).filter(p=>p.status==='Incubadora'&&(+p.progress||0)===0);if(inc.length)a.push(`${inc.length} proyecto${inc.length===1?'':'s'} en incubadora sin avance registrado.`);if((state.operatingPlan.debitarDays||[]).includes(dow)&&daily.debitarHours===0)a.push('Hoy es día DEBITAR y aún no registras horas de trabajo.');if((state.operatingPlan.uberDays||[]).includes(dow)&&daily.uberTurns===0)a.push('Hoy está planificado Uber y aún no registras una jornada.');let ta=taskAttention();if(ta.overdue)a.push(`Tienes ${ta.overdue} tarea${ta.overdue===1?'':'s'} vencida${ta.overdue===1?'':'s'}.`);return a}
function taskCountsV08(){let now=todayISO(),p=(state.tasks||[]).filter(t=>t.status!=='Hecha'),urgent=p.filter(t=>{let d=taskDue(t);return d&&d<=addTaskDays(now,1,false)});return{total:(state.tasks||[]).length,urgent:urgent.length}}
function mailAck(t){let email=t?.clientEmail||'',subject='DEBITAR · Solicitud recibida',body=`Hola,\n\nHemos recibido su solicitud y ya la estamos abordando. Prontamente le avisaremos su resolución o cualquier antecedente adicional que necesitemos.\n\nSaludos,\nDEBITAR`;if(!email)return alert('Esta tarea no tiene correo de cliente registrado.');location.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}

const shellV08Base=shell;
shell=function(){ensureV08();let a=taskAttention(),tc=taskCountsV08();let left=[['Inicio','⌂'],['Finanzas','◫'],['Gastos','↓'],['Deudas','◈']];let right=[['DEBITAR','D'],['Uber','U'],['Proyectos','P'],['Tareas','✓'],['Objetivos','◎'],['Reportes','▤'],['Configuración','⚙']];let buttons=arr=>arr.map(x=>{let badges=x[0]==='Tareas'?`<span class="task-total-badge">${tc.total}</span>${tc.urgent?`<span class="task-badge">${tc.urgent}</span>`:''}`:'';return `<button class="dockbtn ${page===x[0]?'on':''}" data-p="${x[0]}"><span class="dockicon">${x[1]}</span><span class="docklabel">${x[0]}</span>${badges}</button>`}).join('');document.querySelector('#app').innerHTML=`<div class="shell shell-v061"><aside class="side side-left"><img class="logo logo-v08" src="https://danielmunoz-debitar.github.io/centro-operaciones/assets/logo-debitar.png"><div class="nav docknav">${buttons(left)}</div></aside><main class="main"><div class="top"><div class="title"><h1>${page}</h1><p>Centro de Operaciones · v0.8 · trabajo diario DEBITAR</p></div><input class="month" id="month" type="month" value="${state.selectedMonth}"></div><div id="view"></div></main><aside class="side side-right compact-right"><div class="nav docknav">${buttons(right)}</div></aside></div>`;$$('[data-p]').forEach(b=>b.onclick=()=>{page=b.dataset.p;shell()});$('#month').onchange=e=>{state.selectedMonth=e.target.value;save();render()};let d=todayISO();state.usageDays[d]=(state.usageDays[d]||0)+1;save();render();if(!sessionStorage.getItem('v08-daily-alert')){let al=operatingAlerts();if(al.length){sessionStorage.setItem('v08-daily-alert','1');setTimeout(()=>toast(al[0]),350)}}}

const dashboardV08Base=dashboard;
dashboard=function(){let base=dashboardV08Base(),al=operatingAlerts(),wk=weeklyOps(),daily=dailyOps(),plan=state.operatingPlan,scoreParts=[daily.debitarHours>0,daily.tasksDone>0,!plan.uberDays.includes(new Date().getDay())||daily.uberTurns>0],score=Math.round(scoreParts.filter(Boolean).length/scoreParts.length*100);let panel=`<div class="card daily-center"><div class="section"><div><h2>Centro de trabajo diario</h2><small class="muted">El sistema no sólo mira: te empuja a ejecutar.</small></div><span class="pill ${score>=67?'ok':'wait'}">Actividad hoy ${score}%</span></div>${al.length?al.map(x=>`<div class="daily-alert">${esc(x)}</div>`).join(''):'<div class="daily-ok">✓ Sin alertas operativas pendientes hoy.</div>'}<div class="grid four daily-stats">${kpi('DEBITAR semana',num(wk.debitarHours)+' h',`Objetivo ${num(plan.debitarWeeklyHours)} h`)}${kpi('Uber semana',num(wk.uberHours)+' h',`Plan sostenible ${num(plan.uberWeeklyHours)} h`)}${kpi('Tareas hechas hoy',daily.tasksDone,'Ejecución real')}${kpi('Uso del Centro',Object.keys(state.usageDays||{}).length+' días','Días con actividad registrada')}</div></div>`;return panel+base}

const expensesV08Base=expenses;
expenses=function(){let ex=monthExpenses(),cats=[...new Set(ex.map(e=>e.category).filter(Boolean))].sort(),selected=state.expenseFilter||'Todas',filtered=selected==='Todas'?ex:ex.filter(e=>e.category===selected),m=metrics();return `<div class="grid three">${kpi('Total del mes',fmt(m.recurring),'Gastos recurrentes')}${kpi('Pagado',fmt(ex.filter(e=>e.status==='Pagado').reduce((a,e)=>a+(e.paidAmount||e.amount),0)),'Sólo gastos')}${kpi('Por pagar',fmt(ex.filter(e=>e.status!=='Pagado'&&e.status!=='Postergado'&&e.status!=='Eliminado').reduce((a,e)=>a+(+e.amount||0),0)),'Pendiente')}</div><div class="section"><div><h2>Listado de gastos</h2><small class="muted">Filtra por categoría para ver rápidamente qué compone cada grupo.</small></div><div class="actions"><select id="expense-filter" class="month"><option>Todas</option>${cats.map(c=>`<option ${selected===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn" data-act="newexpense">+ Nuevo gasto</button></div></div><div class="card tablewrap"><table><thead><tr><th>Concepto</th><th>Categoría</th><th>Día</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody>${filtered.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(e.category)}</td><td>${e.day||'—'}</td><td class="num">${fmt(e.amount)}</td><td>${e.status==='Pagado'?'<span class="pill ok">Pagado</span>':e.status==='Postergado'?'<span class="pill wait">Postergado</span>':'<span class="pill wait">Pendiente</span>'}</td><td class="actions"><button class="btn ghost sm" data-edit-exp="${e.id}">Editar</button>${e.status==='Pagado'?`<button class="btn ghost sm" data-unpay-exp="${e.id}">Revertir</button>`:`<button class="btn sm" data-pay-exp="${e.id}">Pagar</button>`}</td></tr>`).join('')}</tbody></table>${!filtered.length?'<div class="empty">No hay gastos en esta categoría.</div>':''}</div>`}

const tasksV08Old=tasksPage;
tasksPage=function(){let html=tasksV08Old();return html.replace('<th>Tarea</th>','<th>Tarea</th><th>Canal / correo</th>').replace(/<td><b>(.*?)<\/b><small class="muted block">(.*?)<\/small><\/td><td>/g,'<td><b>$1</b><small class="muted block">$2</small></td><td>—</td><td>')}
// Reemplazo completo para incluir correo y acuse.
tasksPage=function(){let ts=(state.tasks||[]).slice().sort((a,b)=>(taskDue(a)||'9999').localeCompare(taskDue(b)||'9999')),now=todayISO(),pending=ts.filter(t=>t.status!=='Hecha'),done=ts.filter(t=>t.status==='Hecha'),over=pending.filter(t=>taskDue(t)&&taskDue(t)<now),soon=pending.filter(t=>{let d=taskDue(t);return d&&d>=now&&d<=addTaskDays(now,1,false)});return `<div class="grid four">${kpi('Registradas',ts.length,'Número verde en el menú')}${kpi('Vencidas',over.length,over.length?'Requieren atención':'Al día')}${kpi('Próximas 24 h',soon.length)}${kpi('Completadas',done.length)}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="newtask">+ Nueva tarea</button></div><div class="section"><h2>Agenda de trabajo</h2></div><div class="card tablewrap">${ts.length?`<table><thead><tr><th>Estado</th><th>Tarea</th><th>Canal / correo</th><th>Fecha límite</th><th>Prioridad</th><th>Horas</th><th></th></tr></thead><tbody>${ts.map(t=>{let du=taskDue(t),late=t.status!=='Hecha'&&du&&du<now,urgent=t.status!=='Hecha'&&du&&du<=addTaskDays(now,1,false);return `<tr class="${late?'task-overdue':''}"><td><button class="btn ${t.status==='Hecha'?'ghost':''} sm" data-task-toggle="${t.id}">${t.status==='Hecha'?'✓ Hecha':'Pendiente'}</button></td><td><b>${esc(t.title)}</b><small class="muted block">${esc(t.client||'General')} · ${esc(t.note||'')}</small></td><td>${esc(t.channel||'Interno')}<small class="block muted">${esc(t.clientEmail||'—')}</small>${t.clientEmail?`<button class="btn ghost sm" data-ack="${t.id}">Preparar acuse</button>`:''}</td><td><b>${du||'—'}</b>${late?'<small class="block badtext">Vencida</small>':urgent?'<small class="block warntext">Pronto a vencer</small>':''}</td><td><span class="pill ${t.priority==='Alta'?'bad':t.priority==='Media'?'wait':''}">${esc(t.priority||'Media')}</span></td><td>${num(t.hours||0)} h</td><td><button class="btn ghost sm" data-task-edit="${t.id}">Editar</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Crea tareas y registra también las solicitudes que llegan por correo.</div>'}</div>`}

taskModal=function(id){let t=id?(state.tasks||[]).find(x=>x.id===id):null,clients=state.clients.filter(c=>c.active);modal(`<div class="form-grid"><div class="field"><label>Tarea / solicitud</label><input id="tt" value="${esc(t?.title||'')}"></div><div class="field"><label>Cliente / área</label><select id="cl"><option>General DEBITAR</option>${clients.map(c=>`<option ${t?.client===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}<option ${t?.client==='Personal'?'selected':''}>Personal</option></select></div><div class="field"><label>Canal de ingreso</label><select id="ch"><option ${t?.channel==='Email'?'selected':''}>Email</option><option ${t?.channel==='WhatsApp'?'selected':''}>WhatsApp</option><option ${t?.channel==='Teléfono'?'selected':''}>Teléfono</option><option ${!t?.channel||t?.channel==='Interno'?'selected':''}>Interno</option></select></div><div class="field"><label>Correo cliente</label><input id="em" type="email" value="${esc(t?.clientEmail||'')}"></div><div class="field"><label>Fecha de inicio</label><input id="st" type="date" value="${t?.startDate||t?.due||todayISO()}"></div><div class="field"><label>Días asignados</label><input id="dy" type="number" min="0" value="${t?.days||1}"></div><div class="field"><label>Tipo de plazo</label><select id="dt"><option ${t?.dayType!=='Días hábiles'?'selected':''}>Días corridos</option><option ${t?.dayType==='Días hábiles'?'selected':''}>Días hábiles</option></select></div><div class="field"><label>Prioridad</label><select id="pr"><option ${t?.priority==='Alta'?'selected':''}>Alta</option><option ${!t||t?.priority==='Media'?'selected':''}>Media</option><option ${t?.priority==='Baja'?'selected':''}>Baja</option></select></div><div class="field"><label>Horas estimadas</label><input id="hr" type="number" step="0.5" value="${t?.hours||0}"></div><div class="field"><label>Nota</label><input id="no" value="${esc(t?.note||'')}"></div></div><div class="notice">Si la solicitud llegó por email, guarda el correo del cliente. “Preparar acuse” abrirá tu aplicación de correo con el mensaje DEBITAR preescrito.</div><button class="btn" id="sv">Guardar tarea</button>`,b=>{let fillEmail=()=>{let c=clients.find(x=>x.name===$('#cl',b).value);if(c?.email&&!$('#em',b).value)$('#em',b).value=c.email};$('#cl',b).onchange=fillEmail;fillEmail();$('#sv',b).onclick=()=>{let obj=t||{id:uid('task'),status:'Pendiente'};Object.assign(obj,{title:$('#tt',b).value.trim(),client:$('#cl',b).value,channel:$('#ch',b).value,clientEmail:$('#em',b).value.trim(),startDate:$('#st',b).value,days:+$('#dy',b).value||0,dayType:$('#dt',b).value,priority:$('#pr',b).value,hours:+$('#hr',b).value||0,note:$('#no',b).value});obj.due=addTaskDays(obj.startDate,obj.days,obj.dayType==='Días hábiles');if(!obj.title)return alert('Escribe una tarea');if(!t)state.tasks.push(obj);save('Tarea guardada');b.remove();shell()}})}

const toggleTaskV08Base=toggleTask;
toggleTask=function(id){let t=(state.tasks||[]).find(x=>x.id===id);if(!t)return;let makingDone=t.status!=='Hecha';toggleTaskV08Base(id);t=(state.tasks||[]).find(x=>x.id===id);if(t){t.completedAt=makingDone?new Date().toISOString():'';save()}shell()}

objectives=function(){ensureV08();let m=metrics(),r=reserveMetrics(),wk=weeklyOps(),p=state.operatingPlan,incomeTarget=+p.incomeTarget||3000000,indTarget=+p.independenceTarget||2000000,excess=m.income-m.due,uberDepend=m.income?m.uber/m.income*100:0,months=r.free>0&&excess>0?Math.max(0,(r.target-r.free)/excess):null,autonomy=m.due? r.free/m.due:0;return `<div class="objective-hero"><div><span class="eyebrow">AUTONOMÍA FINANCIERA</span><h2>Objetivos que dicen la verdad</h2><p>Más ingresos sólo importan si aumentan tu excedente, tu reserva y tu independencia.</p></div><div><small>Reserva real disponible</small><b>${fmt(r.free)}</b><span>${pct(r.free,r.target)}% de ${fmt(r.target)}</span></div></div><div class="grid four" style="margin-top:14px">${kpi('Saldo Banco de Chile',fmt(r.balance),'Cuenta concentradora')}${kpi('Compromisos pendientes',fmt(r.pending),'Dinero todavía comprometido')}${kpi('Reserva libre',fmt(r.free),`${pct(r.free,r.target)}% de la meta`)}${kpi('Meses de autonomía',num(autonomy),'Reserva ÷ obligaciones mensuales')}</div><div class="grid two" style="margin-top:14px"><div class="card"><h3>Ingreso mensual</h3><div class="big">${fmt(m.income)} / ${fmt(incomeTarget)}</div><div class="bar"><i style="width:${Math.min(100,pct(m.income,incomeTarget))}%"></i></div><p class="muted">${pct(m.income,incomeTarget)}% · calculado automáticamente.</p></div><div class="card"><h3>Independencia DEBITAR</h3><div class="big">${fmt(m.expectedDebitar)} / ${fmt(indTarget)}</div><div class="bar"><i style="width:${Math.min(100,pct(m.expectedDebitar,indTarget))}%"></i></div><p class="muted">Cartera recurrente activa, no ingresos extraordinarios.</p></div><div class="card"><h3>Excedente real del mes</h3><div class="big ${excess>=0?'positive':'negative'}">${fmt(excess)}</div><p class="muted">Ingresos registrados − obligaciones del mes. ${months!==null?`Al ritmo de este excedente, la reserva faltante equivale a ≈ ${num(months)} meses.`:'Todavía no existe excedente positivo para proyectar ahorro.'}</p></div><div class="card"><h3>Dependencia de Uber</h3><div class="big">${num(uberDepend)}%</div><p class="muted">Porción del ingreso actual proveniente de Uber. La meta estructural es que Uber deje de ser necesario para cerrar el mes.</p></div></div><div class="section"><div><h2>Ritmo operativo semanal</h2><small class="muted">Capacidad sostenible, no jornadas infinitas.</small></div><button class="btn ghost" data-act="rhythm">Editar ritmo</button></div><div class="grid three">${kpi('DEBITAR',num(wk.debitarHours)+' / '+num(p.debitarWeeklyHours)+' h','Óptimo semanal')}${kpi('Uber',num(wk.uberHours)+' / '+num(p.uberWeeklyHours)+' h','Plan sostenible semanal')}${kpi('Sueño objetivo',num(p.sleepHours)+' h','Piso diario recomendado por el plan')}</div>`}

function rhythmModal(){let p=state.operatingPlan,days=[['Dom',0],['Lun',1],['Mar',2],['Mié',3],['Jue',4],['Vie',5],['Sáb',6]],checks=(key)=>days.map(([n,v])=>`<label class="daycheck"><input type="checkbox" data-${key}="${v}" ${(p[key]||[]).includes(v)?'checked':''}> ${n}</label>`).join('');modal(`<div class="form-grid"><div class="field"><label>Horas DEBITAR por semana</label><input id="dh" type="number" step="0.5" value="${p.debitarWeeklyHours}"></div><div class="field"><label>Horas Uber sostenibles por semana</label><input id="uh" type="number" step="0.5" value="${p.uberWeeklyHours}"></div><div class="field"><label>Sueño objetivo diario</label><input id="sh" type="number" step="0.5" value="${p.sleepHours}"></div></div><h3>Días DEBITAR</h3><div class="daygrid">${checks('debitarDays')}</div><h3>Días Uber</h3><div class="daygrid">${checks('uberDays')}</div><button class="btn" id="rsv">Guardar ritmo</button>`,b=>$('#rsv',b).onclick=()=>{p.debitarWeeklyHours=+$('#dh',b).value||10;p.uberWeeklyHours=+$('#uh',b).value||9;p.sleepHours=+$('#sh',b).value||7.5;p.debitarDays=$$('[data-debitarDays]',b).filter(x=>x.checked).map(x=>+x.dataset.debitardays);p.uberDays=$$('[data-uberDays]',b).filter(x=>x.checked).map(x=>+x.dataset.uberdays);save('Ritmo semanal actualizado');b.remove();shell()})}

