/* v0.9 COMMERCIAL PIPELINE + DAILY BRIEFING */
function ensureV09(){ensureV08();state.prospects=state.prospects||[];state.prospects.forEach(p=>{p.status=p.status==='Por contactar'?'Prospecto':p.status==='Descartado'?'Perdido':(p.status||'Prospecto');p.source=p.source||'Otro';p.business=p.business||'';p.phone=p.phone||p.contact||'';p.email=p.email||'';p.service=p.service||'';p.nextAction=p.nextAction||p.next||'';p.nextDate=p.nextDate||'';p.lastContact=p.lastContact||'';p.lossReason=p.lossReason||'';p.notes=p.notes||''});state.version=6}
function openProspects(){ensureV09();return state.prospects.filter(p=>!['Ganado','Perdido'].includes(p.status))}
function commercialAttention(){let d=todayISO(),open=openProspects(),due=open.filter(p=>p.nextDate&&p.nextDate<=d),stale=open.filter(p=>p.lastContact&&Math.floor((new Date(d)-new Date(p.lastContact))/86400000)>=7);return{due,stale}}
function operatingBriefing(){ensureV09();let items=[],daily=dailyOps(),dow=new Date().getDay(),plan=state.operatingPlan,ta=taskAttention(),ca=commercialAttention();if(ta.overdue)items.push({level:'bad',text:`${ta.overdue} tarea${ta.overdue===1?'':'s'} vencida${ta.overdue===1?'':'s'}`,action:'Tareas',label:'Ver tareas'});if(ta.soon)items.push({level:'wait',text:`${ta.soon} tarea${ta.soon===1?'':'s'} próxima${ta.soon===1?'':'s'} a vencer`,action:'Tareas',label:'Ver tareas'});if(ca.due.length)items.push({level:'info',text:`${ca.due.length} prospecto${ca.due.length===1?'':'s'} requiere${ca.due.length===1?'':'n'} seguimiento`,action:'DEBITAR',label:'Ver pipeline'});if((plan.debitarDays||[]).includes(dow)&&daily.debitarHours===0)items.push({level:'wait',text:'DEBITAR planificado · aún sin horas hoy',act:'startdebitar',label:'Iniciar DEBITAR'});if((plan.uberDays||[]).includes(dow)&&daily.uberTurns===0)items.push({level:'wait',text:'Uber planificado · aún sin jornada hoy',action:'Uber',label:'Ir a Uber'});let review=(state.projects||[]).filter(p=>p.status==='Incubadora'&&p.target&&p.target<=todayISO());if(review.length)items.push({level:'info',text:`${review.length} proyecto${review.length===1?'':'s'} en incubadora con fecha comprometida`,action:'Proyectos',label:'Ver proyectos'});return items}

prospectModal=function(id){ensureV09();let p=id?state.prospects.find(x=>x.id===id):null;modal(`<div class="form-grid"><div class="field"><label>Nombre contacto</label><input id="prn" value="${esc(p?.name||'')}"></div><div class="field"><label>Negocio / empresa</label><input id="prb" value="${esc(p?.business||'')}"></div><div class="field"><label>Teléfono / WhatsApp</label><input id="prph" value="${esc(p?.phone||'')}"></div><div class="field"><label>Email</label><input id="prem" type="email" value="${esc(p?.email||'')}"></div><div class="field"><label>Origen</label><select id="prsrc">${['Referido','Uber','RRSS','Prospección','Web','Otro'].map(x=>`<option ${p?.source===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Servicio de interés</label><input id="prsvc" value="${esc(p?.service||'')}"></div><div class="field"><label>Valor potencial mensual</label><input id="prfee" type="number" value="${p?.fee||0}"></div><div class="field"><label>Estado</label><select id="prst">${['Prospecto','Contactado','Respondió','Reunión','Propuesta','Ganado','Perdido'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Último contacto</label><input id="prlast" type="date" value="${p?.lastContact||''}"></div><div class="field"><label>Próxima acción</label><input id="prnext" value="${esc(p?.nextAction||'')}"></div><div class="field"><label>Fecha próxima acción</label><input id="prdate" type="date" value="${p?.nextDate||''}"></div><div class="field"><label>Motivo pérdida</label><input id="prloss" value="${esc(p?.lossReason||'')}"></div><div class="field" style="grid-column:1/-1"><label>Notas</label><textarea id="prnotes" rows="3">${esc(p?.notes||'')}</textarea></div></div><div class="actions"><button class="btn" id="prsave">Guardar prospecto</button>${p?.status==='Ganado'?`<button class="btn ghost" id="prconvert">Convertir en cliente</button>`:''}</div>`,b=>{let saveP=()=>{let o=p||{id:uid('pr')};Object.assign(o,{name:$('#prn',b).value.trim(),business:$('#prb',b).value.trim(),phone:$('#prph',b).value.trim(),contact:$('#prph',b).value.trim(),email:$('#prem',b).value.trim(),source:$('#prsrc',b).value,service:$('#prsvc',b).value.trim(),fee:+$('#prfee',b).value||0,status:$('#prst',b).value,lastContact:$('#prlast',b).value,nextAction:$('#prnext',b).value.trim(),next:$('#prnext',b).value.trim(),nextDate:$('#prdate',b).value,lossReason:$('#prloss',b).value.trim(),notes:$('#prnotes',b).value.trim()});if(!o.name&&!o.business)return alert('Ingresa un nombre o negocio');if(!p)state.prospects.push(o);save('Prospecto guardado');return o};$('#prsave',b).onclick=()=>{saveP();b.remove();render()};let cv=$('#prconvert',b);if(cv)cv.onclick=()=>{let o=saveP();if(state.clients.some(c=>c.email&&o.email&&c.email===o.email))return alert('Ya existe un cliente con ese correo.');state.clients.push({id:uid('c'),rut:'',name:o.business||o.name,reps:[],fee:o.fee||0,day:1,email:o.email||'',phone:o.phone||'',vault:null,active:true});save('Prospecto convertido en cliente');b.remove();render()}})}

const debitarV09Base=debitarBase;
debitar=function(){ensureV09();let m=metrics(),cols=collectionsM(),ps=state.prospects,open=openProspects(),won=ps.filter(p=>p.status==='Ganado'),potential=open.reduce((a,p)=>a+(+p.fee||0),0),ca=commercialAttention(),stages=['Prospecto','Contactado','Respondió','Reunión','Propuesta','Ganado','Perdido'];let clients=`<div class="grid kpis">${kpi('Cartera activa',fmt(m.expectedDebitar))}${kpi('Cobrado mes',fmt(m.debitar))}${kpi('Pendiente cartera',fmt(Math.max(0,m.expectedDebitar-m.debitar)))}${kpi('Horas DEBITAR',num(m.debHours)+' h',m.debHours?fmt(m.debitar/m.debHours)+'/h':'Sin horas registradas')}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="startdebitar">▶ Iniciar trabajo DEBITAR</button><button class="btn ghost" data-act="manualdebitar">+ Registrar horas</button><button class="btn ghost" data-act="newclient">+ Cliente</button><button class="btn ghost" data-act="newprospect">+ Prospecto</button></div><div class="section"><h2>Clientes</h2></div><div class="card tablewrap"><table><thead><tr><th>Cliente</th><th>RUT</th><th>Valor</th><th>Día</th><th>Estado mes</th><th></th></tr></thead><tbody>${state.clients.filter(c=>c.active).map(c=>{let co=cols.find(x=>x.clientId===c.id);return `<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.rut||'—')}</td><td class="num">${fmt(c.fee)}</td><td>${c.day}</td><td>${co?.status==='Cobrado'?'<span class="pill ok">Cobrado</span>':'<span class="pill wait">Pendiente</span>'}</td><td class="actions"><button class="btn ghost sm" data-client="${c.id}">Abrir ficha</button>${co?.status==='Cobrado'?'':`<button class="btn sm" data-collect="${c.id}">Registrar cobro</button>`}</td></tr>`}).join('')}</tbody></table></div>`;let pipeline=`<div class="section"><div><h2>Pipeline comercial</h2><small class="muted">Prospecto → Contactado → Respondió → Reunión → Propuesta → Ganado / Perdido</small></div><button class="btn" data-act="newprospect">+ Prospecto</button></div><div class="grid four">${kpi('Pipeline abierto',open.length,'Prospectos activos')}${kpi('Valor potencial',fmt(potential),'Mensual estimado')}${kpi('Seguimientos hoy',ca.due.length,ca.due.length?'Requieren acción':'Al día')}${kpi('Ganados',won.length,ps.length?`${Math.round(won.length/ps.length*100)}% del total registrado`:'Sin historial')}</div><div class="pipeline-board">${stages.map(s=>{let arr=ps.filter(p=>p.status===s);return `<div class="pipe-col"><div class="pipe-head"><b>${s}</b><span>${arr.length}</span></div>${arr.length?arr.map(p=>`<button class="pipe-card" data-prospect="${p.id}"><b>${esc(p.business||p.name)}</b><small>${esc(p.name||'')}</small><span>${esc(p.service||'Sin servicio definido')}</span><em>${fmt(p.fee||0)}/mes</em>${p.nextDate?`<i class="${p.nextDate<=todayISO()&&!['Ganado','Perdido'].includes(p.status)?'due':''}">${esc(p.nextAction||'Seguimiento')} · ${p.nextDate}</i>`:''}</button>`).join(''):'<div class="pipe-empty">Sin registros</div>'}</div>`}).join('')}</div>`;return clients+pipeline}

const dashboardV09Base=dashboardV08Base;
dashboard=function(){ensureV09();let base=dashboardV09Base(),items=operatingBriefing(),wk=weeklyOps(),daily=dailyOps(),plan=state.operatingPlan,scoreParts=[daily.debitarHours>0,daily.tasksDone>0,!plan.uberDays.includes(new Date().getDay())||daily.uberTurns>0],score=Math.round(scoreParts.filter(Boolean).length/scoreParts.length*100);let briefing=items.length?items.map(i=>`<div class="brief-row ${i.level}"><span>${esc(i.text)}</span><button class="btn ghost sm" ${i.action?`data-go="${i.action}"`:`data-act="${i.act}"`}>${esc(i.label)}</button></div>`).join(''):'<div class="daily-ok">✓ Día al día · no tienes alertas operativas pendientes.</div>';return `<div class="card daily-center"><div class="section"><div><h2>Briefing de hoy</h2><small class="muted">Sólo lo que requiere una decisión o una acción.</small></div><span class="pill ${score>=67?'ok':'wait'}">Actividad hoy ${score}%</span></div>${briefing}<div class="grid four daily-stats">${kpi('DEBITAR semana',num(wk.debitarHours)+' h',`Objetivo ${num(plan.debitarWeeklyHours)} h`)}${kpi('Uber semana',num(wk.uberHours)+' h',`Plan sostenible ${num(plan.uberWeeklyHours)} h`)}${kpi('Tareas hechas hoy',daily.tasksDone,'Ejecución real')}${kpi('Uso del Centro',Object.keys(state.usageDays||{}).length+' días','Días con actividad registrada')}</div></div>`+base}

