/* v0.9 COMERCIAL · funnel QR + agenda Google Calendar */
function ensureV09Commercial(){ensureV09();state.prospects.forEach(p=>{p.campaign=p.campaign||'';p.leadTool=p.leadTool||'';p.calculatorResult=p.calculatorResult||'';p.meeting=p.meeting||null});state.version=7}
function googleCalStamp(date,time){return String(date||'').replaceAll('-','')+'T'+String(time||'09:00').replace(':','')+'00'}
function addMinutesToLocal(date,time,mins){let d=new Date(`${date}T${time}:00`);d.setMinutes(d.getMinutes()+mins);let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),da=String(d.getDate()).padStart(2,'0'),h=String(d.getHours()).padStart(2,'0'),mi=String(d.getMinutes()).padStart(2,'0');return {date:`${y}-${m}-${da}`,time:`${h}:${mi}`}}
function scheduleProspect(id){ensureV09Commercial();let p=state.prospects.find(x=>x.id===id);if(!p)return;let defaultDate=p.nextDate||todayISO();modal(`<div class="form-grid"><div class="field"><label>Prospecto</label><input value="${esc(p.business||p.name)}" disabled></div><div class="field"><label>Correo invitado</label><input id="mtEmail" type="email" value="${esc(p.email||'')}"></div><div class="field"><label>Fecha</label><input id="mtDate" type="date" value="${defaultDate}"></div><div class="field"><label>Hora</label><input id="mtTime" type="time" value="19:00"></div><div class="field"><label>Duración</label><select id="mtDur"><option value="30">30 min</option><option value="45">45 min</option><option value="60">60 min</option></select></div><div class="field"><label>Modalidad</label><select id="mtMode"><option>Google Meet</option><option>Telefónica</option><option>Presencial</option></select></div><div class="field" style="grid-column:1/-1"><label>Motivo / diagnóstico</label><input id="mtReason" value="Revisión de rentabilidad y diagnóstico DEBITAR"></div><div class="field" style="grid-column:1/-1"><label>Notas para la invitación</label><textarea id="mtNotes" rows="3">Origen: ${esc(p.source||'')}${p.campaign?` · Campaña: ${esc(p.campaign)}`:''}${p.calculatorResult?`\nResultado calculadora: ${esc(p.calculatorResult)}`:''}</textarea></div></div><div class="actions"><button class="btn" id="mtOpen">Abrir invitación en Google Calendar</button></div><p class="muted">El Centro prepara el evento y el invitado. Google Calendar realiza el envío cuando confirmas/guardas el evento. Para crear Google Meet automáticamente desde el Centro necesitaremos autenticación Google segura.</p>`,b=>{$('#mtOpen',b).onclick=()=>{let email=$('#mtEmail',b).value.trim(),date=$('#mtDate',b).value,time=$('#mtTime',b).value,dur=+$('#mtDur',b).value||30,mode=$('#mtMode',b).value,reason=$('#mtReason',b).value.trim(),notes=$('#mtNotes',b).value.trim();if(!email||!date||!time)return alert('Ingresa correo, fecha y hora.');let end=addMinutesToLocal(date,time,dur),title=`DEBITAR · ${reason}`,details=`Prospecto: ${p.business||p.name}\nContacto: ${p.name||''}\nTeléfono: ${p.phone||''}\nModalidad: ${mode}\n\n${notes}`,params=new URLSearchParams({action:'TEMPLATE',text:title,dates:`${googleCalStamp(date,time)}/${googleCalStamp(end.date,end.time)}`,details,ctz:'America/Santiago',add:email});p.email=email;p.status='Reunión';p.lastContact=todayISO();p.nextAction='Realizar reunión';p.nextDate=date;p.meeting={date,time,duration:dur,mode,email,reason};save('Reunión preparada y prospecto actualizado');window.open('https://calendar.google.com/calendar/render?'+params.toString(),'_blank','noopener');b.remove();render()}})}
prospectModal=function(id){ensureV09Commercial();let p=id?state.prospects.find(x=>x.id===id):null;modal(`<div class="form-grid"><div class="field"><label>Nombre contacto</label><input id="prn" value="${esc(p?.name||'')}"></div><div class="field"><label>Negocio / empresa</label><input id="prb" value="${esc(p?.business||'')}"></div><div class="field"><label>Teléfono / WhatsApp</label><input id="prph" value="${esc(p?.phone||'')}"></div><div class="field"><label>Email</label><input id="prem" type="email" value="${esc(p?.email||'')}"></div><div class="field"><label>Origen</label><select id="prsrc">${['QR Flyer','Meta Ads','Referido','Uber','RRSS','Prospección','Web','WhatsApp','Otro'].map(x=>`<option ${p?.source===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Campaña / código</label><input id="prcamp" placeholder="Ej. FLYER-OCT-01" value="${esc(p?.campaign||'')}"></div><div class="field"><label>Herramienta de entrada</label><select id="prtool">${['','Calculadora Rentabilidad','WhatsApp directo','Formulario web','Referido'].map(x=>`<option ${p?.leadTool===x?'selected':''}>${x||'Sin definir'}</option>`).join('')}</select></div><div class="field"><label>Resultado calculadora</label><input id="prcalc" placeholder="Ej. Margen 12% · utilidad $320.000" value="${esc(p?.calculatorResult||'')}"></div><div class="field"><label>Servicio de interés</label><input id="prsvc" value="${esc(p?.service||'')}"></div><div class="field"><label>Valor potencial mensual</label><input id="prfee" type="number" value="${p?.fee||0}"></div><div class="field"><label>Estado</label><select id="prst">${['Prospecto','Contactado','Respondió','Reunión','Propuesta','Ganado','Perdido'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Último contacto</label><input id="prlast" type="date" value="${p?.lastContact||''}"></div><div class="field"><label>Próxima acción</label><input id="prnext" value="${esc(p?.nextAction||'')}"></div><div class="field"><label>Fecha próxima acción</label><input id="prdate" type="date" value="${p?.nextDate||''}"></div><div class="field"><label>Motivo pérdida</label><input id="prloss" value="${esc(p?.lossReason||'')}"></div><div class="field" style="grid-column:1/-1"><label>Notas</label><textarea id="prnotes" rows="3">${esc(p?.notes||'')}</textarea></div></div><div class="actions"><button class="btn" id="prsave">Guardar prospecto</button>${p?`<button class="btn ghost" id="prschedule">Agendar reunión</button>`:''}${p?.status==='Ganado'?`<button class="btn ghost" id="prconvert">Convertir en cliente</button>`:''}</div>`,b=>{let saveP=()=>{let o=p||{id:uid('pr')};Object.assign(o,{name:$('#prn',b).value.trim(),business:$('#prb',b).value.trim(),phone:$('#prph',b).value.trim(),contact:$('#prph',b).value.trim(),email:$('#prem',b).value.trim(),source:$('#prsrc',b).value,campaign:$('#prcamp',b).value.trim(),leadTool:$('#prtool',b).value,calculatorResult:$('#prcalc',b).value.trim(),service:$('#prsvc',b).value.trim(),fee:+$('#prfee',b).value||0,status:$('#prst',b).value,lastContact:$('#prlast',b).value,nextAction:$('#prnext',b).value.trim(),next:$('#prnext',b).value.trim(),nextDate:$('#prdate',b).value,lossReason:$('#prloss',b).value.trim(),notes:$('#prnotes',b).value.trim()});if(!o.name&&!o.business)return alert('Ingresa un nombre o negocio');if(!p)state.prospects.push(o);save('Prospecto guardado');return o};$('#prsave',b).onclick=()=>{saveP();b.remove();render()};let sch=$('#prschedule',b);if(sch)sch.onclick=()=>{let o=saveP();b.remove();scheduleProspect(o.id)};let cv=$('#prconvert',b);if(cv)cv.onclick=()=>{let o=saveP();if(state.clients.some(c=>c.email&&o.email&&c.email===o.email))return alert('Ya existe un cliente con ese correo.');state.clients.push({id:uid('c'),rut:'',name:o.business||o.name,reps:[],fee:o.fee||0,day:1,email:o.email||'',phone:o.phone||'',vault:null,active:true});save('Prospecto convertido en cliente');b.remove();render()}})}
const debitarV09CommercialBase=debitar;
debitar=function(){ensureV09Commercial();let html=debitarV09CommercialBase();let qr=state.prospects.filter(p=>p.source==='QR Flyer'||p.leadTool==='Calculadora Rentabilidad'),meet=state.prospects.filter(p=>p.status==='Reunión'),won=state.prospects.filter(p=>p.status==='Ganado');let funnel=`<div class="section"><div><h2>Adquisición y agenda</h2><small class="muted">QR / Calculadora → WhatsApp → Pipeline → Reunión → Propuesta → Cliente</small></div></div><div class="grid four">${kpi('Leads QR / calculadora',qr.length,'Atracción medida')}${kpi('Reuniones',meet.length,'Prospectos en reunión')}${kpi('Ganados',won.length,'Conversión comercial')}${kpi('MRR ganado',fmt(won.reduce((a,p)=>a+(+p.fee||0),0)),'Valor mensual potencial cerrado')}</div>`;return funnel+html}
const shellV09CommercialBase=shell;
shell=function(){ensureV09Commercial();shellV09CommercialBase();let p=document.querySelector('.title p');if(p)p.textContent='Centro de Operaciones · v0.9 COMERCIAL · QR + pipeline + agenda'}

/* v0.10 COMERCIAL · CLIENTES COMPACTOS + AGENDA + CAMPAÑAS */
function ensureV10(){ensureV09Commercial();state.campaigns=state.campaigns||[];state.commercialAgenda=Object.assign({days:[1,2,3,4],start:'19:30',end:'22:30',meetingMinutes:25,stepMinutes:30},state.commercialAgenda||{});state.version=8}
function dateLabel(iso){let d=new Date(iso+'T12:00:00');return d.toLocaleDateString('es-CL',{weekday:'short',day:'2-digit',month:'2-digit'})}
function agendaSlots(daysAhead=10){ensureV10();let out=[],cfg=state.commercialAgenda,base=new Date();base.setHours(12,0,0,0);for(let k=0;k<daysAhead;k++){let d=new Date(base);d.setDate(base.getDate()+k);if(!cfg.days.includes(d.getDay()))continue;let iso=d.toISOString().slice(0,10),[sh,sm]=cfg.start.split(':').map(Number),[eh,em]=cfg.end.split(':').map(Number),start=sh*60+sm,end=eh*60+em;for(let t=start;t+cfg.meetingMinutes<=end;t+=cfg.stepMinutes){let time=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0'),busy=state.prospects.some(p=>p.meeting&&p.meeting.date===iso&&p.meeting.time===time);out.push({date:iso,time,busy})}}return out}
function agendaText(){let free=agendaSlots().filter(x=>!x.busy),by={};free.forEach(x=>(by[x.date]??=[]).push(x.time));let dates=Object.keys(by).slice(0,4);if(!dates.length)return 'Por el momento no tengo bloques disponibles. Te confirmaré una alternativa.';return `Hola 👋 Tengo estos horarios disponibles para una reunión DEBITAR de ${state.commercialAgenda.meetingMinutes} minutos:\n\n`+dates.map(d=>`${dateLabel(d)}: ${by[d].join(' · ')}`).join('\n')+'\n\n¿Cuál te acomoda mejor?'}
function copyAvailability(){let txt=agendaText();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(txt).then(()=>toast('Horarios copiados para WhatsApp')).catch(()=>prompt('Copia estos horarios:',txt));else prompt('Copia estos horarios:',txt)}
function agendaConfigModal(){ensureV10();let c=state.commercialAgenda,names=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];modal(`<h3>Agenda comercial</h3><p class="muted">Define los días en que aceptarás reuniones. Los bloques se generan cada 30 min y cada reunión dura 25 min.</p><div class="daygrid">${names.map((n,i)=>`<label class="daycheck"><input type="checkbox" data-aday="${i}" ${c.days.includes(i)?'checked':''}> ${n}</label>`).join('')}</div><div class="form-grid"><div class="field"><label>Desde</label><input id="agStart" type="time" value="${c.start}"></div><div class="field"><label>Hasta</label><input id="agEnd" type="time" value="${c.end}"></div><div class="field"><label>Duración reunión</label><input value="25 min" disabled></div><div class="field"><label>Separación de bloques</label><input value="30 min" disabled></div></div><button class="btn" id="agSave">Guardar agenda</button>`,b=>$('#agSave',b).onclick=()=>{c.days=$$('[data-aday]',b).filter(x=>x.checked).map(x=>+x.dataset.aday);c.start=$('#agStart',b).value||'19:30';c.end=$('#agEnd',b).value||'22:30';c.meetingMinutes=25;c.stepMinutes=30;save('Agenda comercial guardada');b.remove();render()})}
function campaignModal(id){ensureV10();let c=id?state.campaigns.find(x=>x.id===id):null;modal(`<h3>${c?'Editar':'Nueva'} campaña</h3><div class="form-grid"><div class="field"><label>Código</label><input id="cpCode" value="${esc(c?.code||'') }" placeholder="FLYER-RENT-OCT26"></div><div class="field"><label>Nombre</label><input id="cpName" value="${esc(c?.name||'')}"></div><div class="field"><label>Canal</label><select id="cpChannel">${['Flyer QR','Meta Ads','Instagram','WhatsApp','Referidos','Uber','Prospección','Web','Otro'].map(x=>`<option ${c?.channel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Oferta / gancho</label><input id="cpOffer" value="${esc(c?.offer||'Calculadora de rentabilidad')}"></div><div class="field"><label>Inversión $</label><input id="cpInv" type="number" value="${c?.investment||0}"></div><div class="field"><label>Impactos / entregas</label><input id="cpImp" type="number" value="${c?.impressions||0}"></div><div class="field"><label>Escaneos / visitas</label><input id="cpScan" type="number" value="${c?.scans||0}"></div><div class="field"><label>Calculadoras completadas</label><input id="cpCalc" type="number" value="${c?.calculators||0}"></div><div class="field"><label>Estado</label><select id="cpStatus">${['Activa','Pausada','Finalizada'].map(x=>`<option ${c?.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div><button class="btn" id="cpSave">Guardar campaña</button>`,b=>$('#cpSave',b).onclick=()=>{let o=c||{id:uid('camp')};Object.assign(o,{code:$('#cpCode',b).value.trim(),name:$('#cpName',b).value.trim(),channel:$('#cpChannel',b).value,offer:$('#cpOffer',b).value.trim(),investment:+$('#cpInv',b).value||0,impressions:+$('#cpImp',b).value||0,scans:+$('#cpScan',b).value||0,calculators:+$('#cpCalc',b).value||0,status:$('#cpStatus',b).value});if(!o.code)return alert('Ingresa un código de campaña');if(!c)state.campaigns.push(o);save('Campaña guardada');b.remove();render()})}
function campaignStats(c){let ps=state.prospects.filter(p=>p.campaign===c.code),contacts=ps.filter(p=>p.status!=='Prospecto').length,meet=ps.filter(p=>['Reunión','Propuesta','Ganado'].includes(p.status)).length,prop=ps.filter(p=>['Propuesta','Ganado'].includes(p.status)).length,won=ps.filter(p=>p.status==='Ganado'),mrr=won.reduce((a,p)=>a+(+p.fee||0),0),rate=(a,b)=>b?Math.round(a/b*100):0;return{leads:ps.length,contacts,meet,prop,won:won.length,mrr,cac:won.length?c.investment/won.length:null,rCM:rate(meet,contacts),rMP:rate(prop,meet),rPW:rate(won.length,prop)}}
function campaignsBlock(){ensureV10();let cs=state.campaigns;return `<div class="section"><div><h2>Matriz de campañas</h2><small class="muted">Mide qué canal merece repetirse. Umbrales iniciales DEBITAR: contacto→reunión 30% · reunión→propuesta 50% · propuesta→cliente 25%.</small></div><button class="btn ghost" data-act="newcampaign">+ Campaña</button></div>${cs.length?`<div class="campaign-grid">${cs.map(c=>{let s=campaignStats(c),sample=s.contacts>=10,ok=sample&&s.won>=1&&s.rCM>=30&&s.rMP>=50&&s.rPW>=25;return `<button class="campaign-card" data-campaign="${c.id}"><div><b>${esc(c.code)}</b><span class="pill ${ok?'ok':sample?'wait':''}">${!sample?'Muestra insuficiente':ok?'Replicable':'Revisar'}</span></div><small>${esc(c.channel)} · ${esc(c.offer||'')}</small><div class="campaign-metrics"><span>Leads<b>${s.leads}</b></span><span>Reuniones<b>${s.meet}</b></span><span>Clientes<b>${s.won}</b></span><span>MRR<b>${fmt(s.mrr)}</b></span></div><em>C→R ${s.rCM}% · R→P ${s.rMP}% · P→C ${s.rPW}%${s.cac!==null?` · CAC ${fmt(s.cac)}`:''}</em></button>`}).join('')}</div>`:`<div class="card empty">Aún no hay campañas. Crea una para atribuir QR, flyers, Meta, referidos u otros canales.</div>`}`}
function agendaBlock(){let slots=agendaSlots().filter(x=>!x.busy).slice(0,18);return `<div class="section"><div><h2>Agenda comercial</h2><small class="muted">Reuniones de 25 min · bloques ${esc(state.commercialAgenda.start)}–${esc(state.commercialAgenda.end)}</small></div><div class="actions"><button class="btn ghost sm" data-act="copyagenda">Copiar para WhatsApp</button><button class="btn ghost sm" data-act="agendaconfig">Configurar</button></div></div><div class="agenda-slots">${slots.length?slots.map(s=>`<span><b>${dateLabel(s.date)}</b>${s.time}</span>`).join(''):'<div class="empty">No hay bloques libres configurados.</div>'}</div>`}
const debitarV10Base=debitar;
debitar=function(){ensureV10();let m=metrics(),cols=collectionsM(),ps=state.prospects,open=openProspects(),won=ps.filter(p=>p.status==='Ganado'),potential=open.reduce((a,p)=>a+(+p.fee||0),0),ca=commercialAttention(),stages=['Prospecto','Contactado','Respondió','Reunión','Propuesta','Ganado','Perdido'];let clients=`<div class="grid kpis">${kpi('Cartera activa',fmt(m.expectedDebitar))}${kpi('Cobrado mes',fmt(m.debitar))}${kpi('Pendiente cartera',fmt(Math.max(0,m.expectedDebitar-m.debitar)))}${kpi('Horas DEBITAR',num(m.debHours)+' h',m.debHours?fmt(m.debitar/m.debHours)+'/h':'Sin horas registradas')}</div><div class="actions" style="margin-top:14px"><button class="btn" data-act="startdebitar">▶ Iniciar trabajo DEBITAR</button><button class="btn ghost" data-act="manualdebitar">+ Registrar horas</button><button class="btn ghost" data-act="newclient">+ Cliente</button><button class="btn ghost" data-act="newprospect">+ Prospecto</button></div><div class="section"><h2>Clientes</h2><small class="muted">Vista compacta · abre la ficha sólo cuando necesites detalle.</small></div><div class="client-cubes">${state.clients.filter(c=>c.active).map(c=>{let co=cols.find(x=>x.clientId===c.id),paid=co?.status==='Cobrado';return `<div class="client-cube"><div><b>${esc(c.name)}</b><span class="pill ${paid?'ok':'wait'}">${paid?'Cobrado':'Pendiente'}</span></div><small>${fmt(c.fee)} · día ${c.day}</small><div class="actions"><button class="btn ghost sm" data-client="${c.id}">Ficha</button>${paid?'':`<button class="btn sm" data-collect="${c.id}">Cobrar</button>`}</div></div>`}).join('')}</div>`;let pipeline=`<div class="commercial-workbench"><div>${agendaBlock()}</div><div>${campaignsBlock()}</div></div><div class="section"><div><h2>Pipeline comercial</h2><small class="muted">Prospecto → Contactado → Respondió → Reunión → Propuesta → Ganado / Perdido</small></div><button class="btn" data-act="newprospect">+ Prospecto</button></div><div class="grid four">${kpi('Pipeline abierto',open.length,'Prospectos activos')}${kpi('Valor potencial',fmt(potential),'Mensual estimado')}${kpi('Seguimientos hoy',ca.due.length,ca.due.length?'Requieren acción':'Al día')}${kpi('Ganados',won.length,ps.length?`${Math.round(won.length/ps.length*100)}% del total registrado`:'Sin historial')}</div><div class="pipeline-board">${stages.map(s=>{let arr=ps.filter(p=>p.status===s);return `<div class="pipe-col"><div class="pipe-head"><b>${s}</b><span>${arr.length}</span></div>${arr.length?arr.map(p=>`<button class="pipe-card" data-prospect="${p.id}"><b>${esc(p.business||p.name)}</b><small>${esc(p.name||'')}</small><span>${esc(p.service||'Sin servicio definido')}</span><em>${fmt(p.fee||0)}/mes</em>${p.nextDate?`<i class="${p.nextDate<=todayISO()&&!['Ganado','Perdido'].includes(p.status)?'due':''}">${esc(p.nextAction||'Seguimiento')} · ${p.nextDate}</i>`:''}</button>`).join(''):'<div class="pipe-empty">Sin registros</div>'}</div>`}).join('')}</div>`;return clients+pipeline}
const prospectModalV10Base=prospectModal;
prospectModal=function(id){ensureV10();let p=id?state.prospects.find(x=>x.id===id):null;if(!p)return prospectModalV10Base(id);prospectModalV10Base(id);setTimeout(()=>{let b=document.querySelector('.modal-bg:last-of-type .modal');if(!b)return;let camp=b.querySelector('#prcamp');if(camp&&state.campaigns.length){let cur=camp.value;let sel=document.createElement('select');sel.id='prcamp';sel.innerHTML='<option value="">Sin campaña</option>'+state.campaigns.map(c=>`<option value="${esc(c.code)}" ${cur===c.code?'selected':''}>${esc(c.code)} · ${esc(c.channel)}</option>`).join('');camp.replaceWith(sel)}},0)}
const actionV10Base=action;
action=function(a){if(a==='copyagenda')return copyAvailability();if(a==='agendaconfig')return agendaConfigModal();if(a==='newcampaign')return campaignModal();return actionV10Base(a)}
const bindV10Base=bind;
bind=function(){bindV10Base();$$('[data-campaign]').forEach(x=>x.onclick=()=>campaignModal(x.dataset.campaign))}
const shellV10Base=shell;
shell=function(){ensureV10();shellV10Base();let p=document.querySelector('.title p');if(p)p.textContent='Centro de Operaciones · v0.10 COMERCIAL · agenda + campañas + pipeline'}
ensureV10();save();shell();
