function emergencyTrajectory(){ensureV1();let p=state.emergencyPlan,months=['2026-12','2027-01','2027-02','2027-03','2027-04','2027-05','2027-06'],target=+p.start||0,rows=[];months.forEach((m,i)=>{if(i>0)target+=+p.baseMonthly||0;if(m>=p.reliefStart)target+=+p.householdRelief||0;if(m===p.operationRentaMonth)target+=+p.operationRenta||0;target=Math.min(+p.target||3000000,target);let actual=+p.actuals?.[m]||0,ratio=target?actual/target:0,cls=ratio>=.95?'ok':ratio>=.8?'wait':'bad',need=Math.max(0,target-actual);rows.push({m,target,actual,ratio,cls,need})});return rows}
function emergencyBlock(){let p=state.emergencyPlan,rows=emergencyTrajectory();return `<div class="card emergency-card"><div class="split"><div><small class="muted">TRAYECTORIA DIC-26 → JUN-27</small><h3>Fondo de emergencia</h3></div><button class="btn ghost sm" data-act="emergencyconfig">Configurar proyección</button></div><div class="tablewrap"><table><thead><tr><th>Mes</th><th>Meta acumulada</th><th>Real acumulado</th><th>Diferencia</th><th>Cumplimiento</th><th>Estado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.m}</td><td class="num">${fmt(r.target)}</td><td><button class="btn ghost sm" data-emactual="${r.m}">${fmt(r.actual)}</button></td><td class="num">${fmt(r.actual-r.target)}</td><td>${num(r.ratio*100)}%</td><td><span class="pill ${r.cls}">${r.cls==='ok'?'En ruta':r.cls==='wait'?'Atención':'Bajo meta'}</span></td></tr>`).join('')}</tbody></table></div><p class="muted">Proyección separada de los datos reales: los aceleradores no se contabilizan como ahorro hasta que registres el acumulado real.</p></div>`}
function emergencyConfigModal(){let p=state.emergencyPlan;modal(`<h3>Proyección fondo de emergencia</h3><div class="form-grid"><div class="field"><label>Meta final</label><input id="efTarget" type="number" value="${p.target}"></div><div class="field"><label>Saldo inicial proyectado</label><input id="efStart" type="number" value="${p.start}"></div><div class="field"><label>Ahorro base mensual</label><input id="efBase" type="number" value="${p.baseMonthly}"></div><div class="field"><label>Liberación hogar proyectada / mes</label><input id="efRelief" type="number" value="${p.householdRelief}"></div><div class="field"><label>Inicio liberación hogar</label><input id="efReliefStart" type="month" value="${p.reliefStart}"></div><div class="field"><label>Operación Renta extraordinaria</label><input id="efOR" type="number" value="${p.operationRenta}"></div><div class="field"><label>Mes Operación Renta</label><input id="efORMonth" type="month" value="${p.operationRentaMonth}"></div></div><div class="notice">Carla y Operación Renta son supuestos de proyección. No alimentan los indicadores reales automáticamente.</div><button class="btn" id="efSave">Guardar proyección</button>`,b=>$('#efSave',b).onclick=()=>{p.target=+$('#efTarget',b).value||3000000;p.start=+$('#efStart',b).value||0;p.baseMonthly=+$('#efBase',b).value||0;p.householdRelief=+$('#efRelief',b).value||0;p.reliefStart=$('#efReliefStart',b).value;p.operationRenta=+$('#efOR',b).value||0;p.operationRentaMonth=$('#efORMonth',b).value;save('Proyección actualizada');b.remove();render()})}
function emergencyActualModal(m){let p=state.emergencyPlan;modal(`<h3>Ahorro real acumulado · ${m}</h3><div class="field"><label>Monto real reservado</label><input id="efa" type="number" value="${p.actuals?.[m]||0}"></div><button class="btn" id="efas">Guardar real</button>`,b=>$('#efas',b).onclick=()=>{p.actuals??={};p.actuals[m]=+$('#efa',b).value||0;let o=state.objectives.find(x=>/Fondo de emergencia/i.test(x.name));if(o&&m===state.selectedMonth)o.current=p.actuals[m];save('Ahorro real actualizado');b.remove();render()})}
