  function card(){let today=todayISO(),all=followups(),pending=all.filter(t=>t.status!=='Hecha').sort((a,b)=>due(a).localeCompare(due(b))),over=pending.filter(t=>due(t)&&due(t)<today),done=all.filter(t=>t.status==='Hecha');return `<div class="card followup-panel"><div class="section"><div><h2>Seguimiento de clientes</h2><small class="muted">Contactos proactivos · integrado con tu agenda de tareas</small></div><button class="btn sm" data-followup-new="1">+ Programar contacto</button></div><div class="followup-stats"><span><b>${pending.length}</b> pendientes</span><span class="${over.length?'negative':''}"><b>${over.length}</b> vencidos</span><span><b>${done.length}</b> realizados</span></div>${pending.length?pending.slice(0,12).map(t=>{let c=clientFor(t),late=due(t)&&due(t)<today;return `<div class="followup-row"><div class="followup-main"><b>${esc(t.client||c?.name||'Cliente')}</b><small>${esc(t.subject||t.title||'Seguimiento')} · ${esc(due(t)||'Sin fecha')} ${late?'· VENCIDO':''}</small></div><div class="followup-actions"><button class="btn ghost sm" data-followup-message="${esc(t.id)}">WhatsApp</button><button class="btn ghost sm" data-followup-done="${esc(t.id)}">✓ Realizado</button></div></div>`}).join(''):'<div class="empty">No hay seguimientos pendientes. Programa un contacto cuando tengas una gestión relevante que comunicar.</div>'}${done.length?`<details class="followup-history"><summary>Historial de contactos realizados (${done.length})</summary>${done.slice(-12).reverse().map(t=>`<div class="followup-row"><div><b>${esc(t.client||'Cliente')}</b><small>${esc(t.subject||t.title)} · ${esc((t.contactAt||t.completedAt||'').slice(0,10)||'Fecha no registrada')}</small></div></div>`).join('')}</details>`:''}<small class="muted block">Los mensajes se preparan para revisión. No se envían automáticamente.</small></div>`}
  tasksPage=function(){return card()+previousTasksPage()};
  function followupModal(){const clients=state.clients.filter(c=>c.active);if(!clients.length)return alert('Primero registra un cliente activo.');modal(`<h3>Programar seguimiento</h3><div class="form-grid"><div class="field"><label>Cliente</label><select id="fuClient">${clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fecha del contacto</label><input id="fuDate" type="date" value="${todayISO()}"></div><div class="field"><label>Motivo</label><select id="fuSubject"><option>Revisión de pendientes</option><option>Solicitar documentos</option><option>Informar avance de gestión</option><option>Recordatorio de vencimiento</option><option>Resumen semanal</option><option>Otro seguimiento</option></select></div><div class="field"><label>Prioridad</label><select id="fuPriority"><option>Media</option><option>Alta</option><option>Baja</option></select></div><div class="field" style="grid-column:1/-1"><label>Observación para el mensaje (opcional)</label><textarea id="fuNote" rows="3" placeholder="Información concreta para este cliente"></textarea></div></div><div class="actions"><button class="btn" id="fuSave">Guardar seguimiento</button></div>`,b=>{$('#fuSave',b).onclick=()=>{let c=state.clients.find(x=>x.id===$('#fuClient',b).value),subject=$('#fuSubject',b).value,date=$('#fuDate',b).value;if(!c||!date)return alert('Selecciona cliente y fecha');state.tasks.push({id:uid('task'),kind:'client-followup',clientId:c.id,client:c.name,title:'Seguimiento · '+subject,subject,note:$('#fuNote',b).value.trim(),due:date,priority:$('#fuPriority',b).value,status:'Pendiente',hours:0,channel:'WhatsApp'});save('Seguimiento programado');b.remove();render()}})}
  function openMessage(id){let t=followups().find(x=>x.id===id);if(!t)return;let c=clientFor(t),phone=String(c?.phone||'').replace(/\D/g,''),msg=message(t);modal(`<h3>Preparar WhatsApp · ${esc(t.client||'Cliente')}</h3><p class="muted">Revisa el texto antes de enviarlo. Abrir WhatsApp no marca el contacto como realizado.</p><div class="field"><label>Mensaje editable</label><textarea id="fuText" rows="8">${esc(msg)}</textarea></div><div class="actions"><button class="btn" id="fuOpen">Abrir WhatsApp</button><button class="btn ghost" id="fuCopy">Copiar texto</button></div>${!phone?'<p class="muted">El cliente no tiene teléfono registrado; WhatsApp se abrirá sin destinatario.</p>':''}`,b=>{$('#fuOpen',b).onclick=()=>{let text=$('#fuText',b).value;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank')};$('#fuCopy',b).onclick=()=>{let text=$('#fuText',b).value;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>alert('Mensaje copiado')).catch(()=>window.prompt('Copia el mensaje:',text));else window.prompt('Copia el mensaje:',text)}})}
  function markDone(id){let t=followups().find(x=>x.id===id);if(!t)return;if(!confirm('¿Confirmas que efectivamente realizaste este contacto?'))return;t.status='Hecha';t.contactAt=new Date().toISOString();t.completedAt=t.contactAt;save('Contacto registrado');render()}
  bind=function(){previousBind();$$('[data-followup-new]').forEach(x=>x.onclick=followupModal);$$('[data-followup-message]').forEach(x=>x.onclick=()=>openMessage(x.dataset.followupMessage));$$('[data-followup-done]').forEach(x=>x.onclick=()=>markDone(x.dataset.followupDone))};
  action=function(a){if(a==='newfollowup')return followupModal();return previousAction(a)};
  shell();
