/* DEBITAR v1.1 - MANUAL PERIOD CONTROL (new independent publication) */
(function(){
 const baseShell=shell,baseRender=render;
 function pc(){if(!state.periodControl||typeof state.periodControl!=='object'){
  const months=new Set([state.selectedMonth]);
  Object.keys(state.expenseMonths||{}).forEach(m=>months.add(m));
  Object.keys(state.clientMonthly||{}).forEach(m=>months.add(m));
  (state.collections||[]).forEach(x=>x.month&&months.add(x.month));
  (state.incomes||[]).forEach(x=>x.date&&months.add(x.date.slice(0,7)));
  (state.uberTurns||[]).forEach(x=>x.start&&months.add(x.start.slice(0,7)));
  state.periodControl={};months.forEach(m=>{if(/^\d{4}-\d{2}$/.test(m))state.periodControl[m]={status:'open',legacy:true}});save();
 }return state.periodControl;}
 function exportBeforeClose(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=u;a.download='DEBITAR-respaldo-'+state.selectedMonth+'-antes-cierre.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);
 }
 function decorate(){
  const top=document.querySelector('.top'),view=document.querySelector('#view');if(!top||!view)return;
  const m=state.selectedMonth,p=pc()[m],status=p?.status||'unopened';
  let bar=document.querySelector('#period-controls');if(!bar){bar=document.createElement('div');bar.id='period-controls';top.insertAdjacentElement('afterend',bar)}
  bar.style.cssText='display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:12px;margin:10px 0;border:1px solid #41617d;border-radius:12px;background:#10283d;color:#f1f7ff';
  bar.innerHTML='<strong>Período '+m+'</strong><span style="padding:5px 9px;border-radius:8px;background:#294762">'+(status==='open'?'ABIERTO':status==='closed'?'CERRADO':'SIN ABRIR')+'</span><button id="period-action" type="button" style="background:#2466a2;color:white;border:0;border-radius:8px;padding:9px 12px;cursor:pointer">'+(status==='open'?'Cerrar mes':status==='closed'?'Reabrir mes':'Abrir mes')+'</button><small>Apertura y cierre exclusivamente manuales</small>';
  bar.querySelector('button').onclick=()=>{
   if(status==='open'){
    if(!confirm('¿Cerrar '+m+'? Primero se descargará un respaldo de todos tus datos.'))return;
    exportBeforeClose();if(!confirm('Verifica que se descargó el respaldo. ¿Confirmas bloquear '+m+'?'))return;
    pc()[m]={...p,status:'closed',closedAt:new Date().toISOString()};
   }else if(status==='closed'){
    if(!confirm('¿Reabrir '+m+' para permitir correcciones?'))return;
    pc()[m]={...p,status:'open',reopenedAt:new Date().toISOString()};
   }else{
    if(!confirm('¿Abrir '+m+'? No se borrarán registros anteriores ni saldos.'))return;
    pc()[m]={status:'open',openedAt:new Date().toISOString()};
   }save();render();
  };
  if(status!=='open'){
   view.innerHTML='<div class="card" style="padding:24px;background:#142e48;color:#eaf4ff"><h2>'+(status==='closed'?'Período cerrado':'Período sin abrir')+'</h2><p>Los registros se conservan. Para trabajar en este período, utiliza '+(status==='closed'?'Reabrir mes':'Abrir mes')+'.</p></div>';
  }
 }
 shell=function(){baseShell();decorate()};render=function(){baseRender();decorate()};pc();decorate();
})();

/* DEBITAR visual stabilization v1.1.2 */
(function(){
 const originalRender=render;
 render=function(){
   originalRender();
   if(page==='Inicio'){
     const root=document.querySelector('#view');
     if(root)for(const title of ['Decisión rápida','Origen de ingresos']){
       const h=[...root.querySelectorAll('h1,h2,h3,h4')].find(x=>x.textContent.trim()===title);
       h?.closest('.card')?.remove();
     }
   }
 };
 if(page==='Inicio')render();
})();
